NEW_FILES['backend/app/engine/emc/emc_live_core.py'] = '# backend/app/engine/emc/emc_live_core.py\n#\n# ── EMC_V1 LIVE CORE ── PURE (no broker / DB imports; unit-tested)\n# Fence: EMC_V1_LIVE_20261011\n# ============================================================================\n# THE PARITY DESIGN (VET / PST doctrine): this file holds NO decision logic.\n# Decisions are app.backtest.emc.emc_v1_engine.EmcDayCore — the very object\n# the backtest\'s simulate_day drives — and every indicator is re-computed by\n# the backtest\'s own functions over the growing day prefix:\n#\n#   * LiveSpotCrosses — spot 1m candles (prior sessions + today, FROZEN once\n#     accepted) → resample_session → spot_crosses on a FRESH EmaPair each\n#     time. Same arithmetic, same continuity, same first-candle (gap) rule\n#     and the same R1 "advance on every session" warm-up as the runner.\n#     A PrefixGuard freezes the strategy if any already-reported cross is\n#     ever restated (a corpus gap or duplicated minute would do that).\n#   * LiveOptionTrack — the selected contract\'s prior-session bars + today\'s\n#     frozen 1m candles → a FRESH OptionEmaTrack evaluated at minute k.\n#     OptionEmaTrack is causal (proven minute-by-minute against a brute-force\n#     recompute in test_emc_runner_sim), so prefix data gives the backtest\'s\n#     value exactly.\n#   * live_params(cfg) — the runner\'s own _merge_cfg + validate + DayParams\n#     build: one config vocabulary, no second parser.\n#\n# WHAT THIS FILE REFUSES (fail closed, by live_problems):\n#   * trail_on — the sealed config has it OFF; a live trailing stop would\n#     need its own parity study (peak through the previous minute).\n#   * fill_mode "close" — a live order cannot fill at a past close; live is\n#     inherently the "next_open" model the seal was tested with.\n# ============================================================================\n\nfrom __future__ import annotations\n\nfrom typing import Dict, List, Optional, Sequence, Tuple\n\ntry:\n    from app.backtest.emc.emc_v1_engine import (EmcBar, EmaPair, OptionEmaTrack, DayParams,\n                                                resample_session, spot_crosses, SESSION_OPEN_MIN)\nexcept ImportError:                                        # standalone tests\n    from emc_v1_engine import (EmcBar, EmaPair, OptionEmaTrack, DayParams,  # type: ignore\n                               resample_session, spot_crosses, SESSION_OPEN_MIN)\n\nIST_OFFSET = 5 * 3600 + 30 * 60\n\n\ndef day_start_epoch_of(ts: int) -> int:\n    """00:00 IST of the day containing ts (the corpus / runner day anchor)."""\n    return ((int(ts) + IST_OFFSET) // 86400) * 86400 - IST_OFFSET\n\n\ndef minute_of(ts: int) -> int:\n    return ((int(ts) + IST_OFFSET) % 86400) // 60\n\n\ndef _bar(c) -> EmcBar:\n    if isinstance(c, EmcBar):\n        return c\n    return EmcBar(int(c["ts"]), float(c["open"]), float(c["high"]), float(c["low"]), float(c["close"]))\n\n\ndef _group_sessions(candles: Sequence) -> List[Tuple[int, List[EmcBar]]]:\n    by: Dict[int, List[EmcBar]] = {}\n    for c in candles:\n        b = _bar(c)\n        by.setdefault(day_start_epoch_of(b.ts), []).append(b)\n    return [(ds, sorted(v, key=lambda x: x.ts)) for ds, v in sorted(by.items())]\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  config — the runner\'s vocabulary, verbatim\n# ─────────────────────────────────────────────────────────────────────────\ndef live_params(cfg: dict) -> Tuple[Optional[DayParams], dict, Optional[str]]:\n    """→ (DayParams | None, merged cfg, problem | None). Uses the backtest\n    runner\'s _merge_cfg / validate / _hhmm so the live engine reads a config\n    exactly as a backtest run would."""\n    from app.backtest.emc.backtest_emc_runner import _merge_cfg, validate, _hhmm\n    m = _merge_cfg(cfg or {})\n    bad = validate(m) or live_problems(m)\n    if bad:\n        return None, m, bad\n    p = DayParams(\n        sel_lo=m["sel_prem_min"], sel_hi=m["sel_prem_max"], sel_pick=m["sel_pick"],\n        direction=m["direction"], intrabar=m["opt_check"] == "intrabar",\n        opt_min_bars=m["opt_min_bars"] or m["ema_slow"], fill=m["fill_mode"],\n        sl_pts=m["sl_pts"], tp_pts=m["tp_pts"], trail_on=m["trail_on"],\n        trail_trigger=m["trail_trigger_pts"], trail_gap=m["trail_gap_pts"], xover_exit=m["xover_exit"],\n        block_min=_hhmm(m["entry_cutoff"], 14 * 60 + 30), eod_min=_hhmm(m["eod_square_off"], 15 * 60 + 15),\n        max_trades=m["max_trades_per_day"], max_losses=m["max_losses_per_day"],\n        skip_from=_hhmm(m["arm_skip_from"], -1) if m.get("arm_skip_from") else -1,\n        skip_to=_hhmm(m["arm_skip_to"], -1) if m.get("arm_skip_to") else -1)\n    return p, m, None\n\n\ndef live_problems(m: dict) -> Optional[str]:\n    if m.get("trail_on"):\n        return "trailing SL is not supported in paper/live (sealed config has it OFF) — refusing to trade"\n    if m.get("fill_mode") == "close":\n        return "fill_mode \'close\' cannot be executed live (orders fill after the decision) — set next_open"\n    if str(m.get("underlying", "NIFTY")).upper() != "NIFTY":\n        return "EMC_V1 paper/live is NIFTY-only"\n    return None\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  prefix guard\n# ─────────────────────────────────────────────────────────────────────────\nclass CrossGuard:\n    """A cross reported for a completed spot bar must never change or vanish\n    as later candles arrive. On violation: FREEZE (no new setups; an open\n    position is still managed to its exit)."""\n\n    def __init__(self) -> None:\n        self.seen: Dict[int, int] = {}\n        self.frozen = False\n        self.reason: Optional[str] = None\n\n    def check(self, crosses: Dict[int, int], upto_min: int) -> bool:\n        if self.frozen:\n            return False\n        for m, x in self.seen.items():\n            if m <= upto_min and crosses.get(m, 0) != x:\n                self.frozen = True\n                self.reason = f"spot cross at minute {m} restated {x} → {crosses.get(m, 0)} — prefix instability"\n                return False\n        for m, x in crosses.items():\n            if m <= upto_min:\n                self.seen[m] = x\n        return True\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  spot crosses over the growing prefix\n# ─────────────────────────────────────────────────────────────────────────\nclass LiveSpotCrosses:\n    def __init__(self, *, fast: int, slow: int, tf: int, warm_sessions_1m: Sequence[Sequence],\n                 need_sessions: int, first_candle_cross: bool = True):\n        self.fast, self.slow, self.tf = int(fast), int(slow), int(tf)\n        self.first_candle_cross = bool(first_candle_cross)\n        self.need = int(need_sessions)\n        warm: List[EmcBar] = []\n        for sess in warm_sessions_1m:\n            for b in sess:\n                warm.append(_bar(b))\n        self.warm_sessions = _group_sessions(warm)\n        self.today: List[EmcBar] = []\n        self.ds: Optional[int] = None\n        self.guard = CrossGuard()\n        self.crosses: Dict[int, int] = {}\n        self.gap_cross_min: Optional[int] = None\n        self.last_vals: Tuple[Optional[float], Optional[float]] = (None, None)\n\n    def warmup_ok(self) -> bool:\n        return len(self.warm_sessions) >= self.need\n\n    def add(self, candle) -> bool:\n        """Freeze one COMPLETED 1m spot candle of today. Out-of-order or\n        duplicate minutes are ignored (False)."""\n        b = _bar(candle)\n        if self.ds is None:\n            self.ds = day_start_epoch_of(b.ts)\n        if day_start_epoch_of(b.ts) != self.ds:\n            return False\n        if self.today and b.ts <= self.today[-1].ts:\n            return False\n        if minute_of(b.ts) < SESSION_OPEN_MIN:\n            return False\n        self.today.append(b)\n        return True\n\n    def last_minute(self) -> Optional[int]:\n        return minute_of(self.today[-1].ts) if self.today else None\n\n    def recompute(self) -> Dict[int, int]:\n        """Crosses of today\'s COMPLETED spot bars, keyed by bar end minute —\n        the runner\'s R1 / R6 computation on the current prefix."""\n        if self.ds is None:\n            return {}\n        pair = EmaPair(self.fast, self.slow)\n        for wds, wb in self.warm_sessions:\n            for b in resample_session(wb, day_start_epoch=wds, tf_minutes=self.tf):\n                pair.update(b.close)\n        upto = self.last_minute() or -1\n        bars = [b for b in resample_session(self.today, day_start_epoch=self.ds, tf_minutes=self.tf)\n                if b.end_min <= upto]                     # completed buckets only\n        xs = spot_crosses(bars, pair)\n        self.last_vals = pair.values\n        self.gap_cross_min = None\n        if bars and (bars[0].ts - self.ds) // 60 == SESSION_OPEN_MIN and bars[0].end_min in xs:\n            self.gap_cross_min = bars[0].end_min\n            if not self.first_candle_cross:\n                del xs[bars[0].end_min]\n        if not self.guard.check(xs, upto):\n            return self.crosses\n        self.crosses = xs\n        return xs\n\n\n# ─────────────────────────────────────────────────────────────────────────\n#  the selected option\'s EMA over the growing prefix\n# ─────────────────────────────────────────────────────────────────────────\nclass LiveOptionTrack:\n    """Drop-in for the runner\'s OptionEmaTrack (same .at(k, intrabar))."""\n\n    def __init__(self, *, fast: int, slow: int, tf: int, ds: int, warm_bars: Sequence[EmcBar]):\n        self.fast, self.slow, self.tf, self.ds = int(fast), int(slow), int(tf), int(ds)\n        self.warm_bars = list(warm_bars)\n        self.today: List[EmcBar] = []\n\n    def add(self, candle) -> bool:\n        b = _bar(candle)\n        if day_start_epoch_of(b.ts) != self.ds:\n            return False\n        if self.today and b.ts <= self.today[-1].ts:\n            return False\n        self.today.append(b)\n        return True\n\n    def at(self, k: int, intrabar: bool = True):\n        known = [b for b in self.today if (b.ts - self.ds) // 60 <= k]\n        tr = OptionEmaTrack(fast=self.fast, slow=self.slow, tf=self.tf, ds=self.ds,\n                            warm_bars=self.warm_bars, today_1m=known)\n        return tr.at(k, intrabar)\n\n\ndef option_warm_from_sessions(sessions: Sequence[Tuple[int, Sequence]], tf: int) -> List[EmcBar]:\n    """The runner\'s option_warm_bars on already-fetched prior sessions\n    [(day_start, candles)], oldest first."""\n    out: List[EmcBar] = []\n    for ds, cs in sessions:\n        out.extend(resample_session([_bar(c) for c in cs], day_start_epoch=ds, tf_minutes=tf))\n    return out\n'

NEW_FILES['backend/app/engine/emc/emc_manager.py'] = '# backend/app/engine/emc/emc_manager.py\n#\n# ── EMC_V1 MANAGER ── orders + persistence for "Ember". Fence: EMC_V1_LIVE_20261011\n#\n# Decisions live in EmcDayCore (the backtest\'s own object, driven by\n# emc_engine); this class owns fills, paper rows, notifications and the kill\n# path. Cloned from OrbManager (the fleet\'s newest single-long-option donor,\n# day-1 scars included):\n#   * fallbacks split per concern; any degraded persistence import REFUSES\n#     new entries (never trade from memory);\n#   * LIVE exits are reconcile-first (never sell without a positive holdings\n#     read; unreadable broker → back off, never guess);\n#   * generic paper_trades storage (PAPER / LIVE rows; PAPER_LIVE twins are\n#     booked by the shadow book inside paper_trades_repo).\n#\n# NO GTT LAYER (ORB / VET doctrine): SL, TP and EOD are ENGINE exits taken\n# at market while the app runs. Divergence ledger vs the backtest:\n#   1. backtest books SL/TP AT the level (open if gapped); paper books at the\n#      first polled LTP through the level (realistic — the paper phase exists\n#      to MEASURE slippage); LIVE takes the market fill.\n#   2. backtest enters at the next minute\'s open; paper/live enter at the\n#      quote/fill taken right after the decision minute closes.\n#   3. if the app is down there is no stop at the broker.\n\nfrom __future__ import annotations\n\nimport time\nimport uuid\nfrom typing import Callable, Optional\n\ntry:\n    from app.risk import execution_modes as _xm\nexcept Exception:                                          # standalone tests\n    class _xm:                                             # type: ignore\n        @staticmethod\n        def normalize(raw, default="PAPER"):\n            m = str(raw or default).strip().upper().replace("+", "_").replace(" ", "_")\n            return m if m in ("OFF", "PAPER", "LIVE", "PAPER_LIVE") else default\n\nSTRATEGY_ID = "EMC_V1"\nFILL_TIMEOUT_S = 20\nFILL_POLL_S = 1.0\n\n_DEGRADED = []\n\ntry:\n    from app.event_bus.audit_logger import write_audit_log\nexcept ImportError:\n    _DEGRADED.append("audit_logger")\n    def write_audit_log(msg):                              # type: ignore\n        print(msg)\n\ntry:\n    from app.event_bus.inapp_events import record_alert\nexcept ImportError:\n    _DEGRADED.append("inapp_events")\n    def record_alert(*a, **k):                             # type: ignore\n        print("ALERT", a, k)\n\ntry:\n    from app.db.paper_trades_repo import insert_paper_trade, close_paper_trade, get_conn\nexcept ImportError:\n    _DEGRADED.append("paper_trades_repo")\n    insert_paper_trade = close_paper_trade = get_conn = None  # type: ignore\n\ntry:\n    from app.config.strategy_loader import load_strategy_config\nexcept ImportError:\n    _DEGRADED.append("strategy_loader")\n    load_strategy_config = None  # type: ignore\n\ntry:\n    from app.backtest.charges.charges_model import charges_for_long_trade\nexcept ImportError:\n    _DEGRADED.append("charges_model")\n    charges_for_long_trade = None  # type: ignore\n\n\ndef levels_for(fill_px: float, sl_pts: float, tp_pts: float):\n    """The core\'s own SL/TP arithmetic (EmcDayCore._try_enter) — one place."""\n    sl = round(fill_px - sl_pts, 2) if sl_pts > 0 else None\n    tp = round(fill_px + tp_pts, 2) if tp_pts > 0 else None\n    return sl, tp\n\n\nclass EmcPosition:\n    def __init__(self, **k):\n        self.__dict__.update(k)\n\n\nclass EmcManager:\n    """One instance per process. The engine calls open_trade / close_trade /\n    check_exits; state routes read state(); kill_switch calls kill_all()."""\n\n    def __init__(self, executor=None, *, cfg_fn: Optional[Callable] = None, notifier=None,\n                 clock: Callable[[], float] = time.time, sleep: Callable[[float], None] = time.sleep):\n        self.executor = executor\n        self.cfg_fn = cfg_fn\n        self.notifier = notifier\n        self.clock = clock\n        self.sleep = sleep\n        self.pos: Optional[EmcPosition] = None\n        self.day_lots: Optional[int] = None\n        self._allow_degraded = False          # tests only — never set live\n        self._close_backoff_n = 0\n        self._close_backoff_until = 0.0\n        # engine hook: called with (minute_epoch, exit_px, reason) for every\n        # close the MANAGER originates (SL/TP/EOD/KILL/BROKER_FLAT) so the\n        # day core counts it toward the losing-trade cap.\n        self.on_closed: Optional[Callable[[int, float, str], None]] = None\n        self.day_stats = {"entries": 0, "exits": {}, "refused": None}\n        self.last_closed_qty: Optional[int] = None\n\n    # ── config / mode ──\n    def cfg(self) -> dict:\n        if self.cfg_fn:\n            return self.cfg_fn() or {}\n        if load_strategy_config is None:\n            return {}\n        try:\n            return load_strategy_config(STRATEGY_ID) or {}\n        except Exception:\n            return {}\n\n    def mode(self) -> str:\n        m = _xm.normalize(self.cfg().get("trade_execution_mode", "PAPER"))\n        return "LIVE" if m == "PAPER_LIVE" else m          # twin booked by paper_trades_repo\n\n    def attach_executor(self, executor) -> None:\n        self.executor = executor\n\n    def qty(self):\n        cfg = self.cfg()\n        lots = int(self.day_lots or cfg.get("lots") or 1)\n        lot_size = int(cfg.get("lot_size") or 0) or 65\n        return lots, lot_size, lots * lot_size\n\n    def net_of(self, entry: float, exit_px: float, qty: Optional[int] = None) -> float:\n        q = int(qty if qty is not None else (self.pos.qty if self.pos else self.qty()[2]))\n        ch = 0.0\n        if charges_for_long_trade is not None:\n            ch = charges_for_long_trade(entry_price=float(entry), exit_price=float(exit_px), qty=q).total_charges\n        return round((float(exit_px) - float(entry)) * q - ch, 2)\n\n    def _alert(self, code, msg, severity="warning"):\n        write_audit_log(f"[EMC][{code}] {msg}")\n        try:\n            record_alert(code, msg, severity=severity, strategy_id=STRATEGY_ID)\n        except Exception:\n            pass\n\n    def _notify(self, fn_name, payload):\n        target = self.notifier\n        if target is None:\n            try:\n                from app.api import telegram_api as target\n            except Exception:\n                return\n        try:\n            getattr(target, fn_name)(payload)\n        except Exception as e:\n            write_audit_log(f"[EMC][NOTIFY_FAIL] {fn_name}: {e!r}")\n\n    # ── entry ──\n    def open_trade(self, *, symbol: str, token: int, side: str, ltp: Optional[float],\n                   entry_spot: Optional[float], decision_ts: int, sl_pts: float, tp_pts: float,\n                   note: str = "") -> Optional[float]:\n        """Buy one position. Returns the fill price, or None when no position\n        was opened (every refusal is alerted)."""\n        if _DEGRADED and not self._allow_degraded:\n            self._alert("PERSIST_DOWN", f"degraded imports {_DEGRADED} — REFUSING to trade "\n                        "(never trade from memory)", "critical")\n            return None\n        if self.pos is not None:\n            self._alert("DOUBLE_ENTRY", f"{symbol} refused — a position is already open", "error")\n            return None\n        mode = self.mode()\n        if mode == "OFF":\n            write_audit_log(f"[EMC][MODE_OFF] {side} {symbol} entry ignored — strategy OFF")\n            return None\n        lots, lot_size, qty = self.qty()\n        if mode == "LIVE":\n            if self.executor is None:\n                self._alert("NO_EXECUTOR", "LIVE entry impossible — executor missing; entry forfeited", "error")\n                return None\n            required = ("place_buy", "place_market_sell", "get_order_fill", "get_open_positions_or_none")\n            missing = [m for m in required if not callable(getattr(self.executor, m, None))]\n            if missing:\n                self._alert("EXEC_CONTRACT", f"LIVE blocked — executor missing {missing}; ZERO orders placed",\n                            "error")\n                return None\n            try:\n                order_id, avg, filled = self.executor.place_buy(symbol, int(token or 0), qty)\n            except Exception as e:\n                self._alert("BUY_FAIL", f"{symbol}: {e!r}", "error")\n                return None\n            fill_px, ok = float(avg or 0.0), bool(filled == qty and avg)\n            t0 = self.clock()\n            while not ok and self.clock() - t0 < FILL_TIMEOUT_S:\n                self.sleep(FILL_POLL_S)\n                try:\n                    st = self.executor.get_order_fill(order_id)\n                except Exception:\n                    continue\n                status = (st or {}).get("status")\n                if status == "COMPLETE":\n                    fill_px, ok = float(st.get("avg_price") or 0.0), True\n                elif status in ("REJECTED", "CANCELLED") and (st or {}).get("found"):\n                    self._alert("BUY_DEAD", f"{symbol} order {status}", "error")\n                    return None\n            if not ok or fill_px <= 0:\n                self._alert("FILL_TIMEOUT", f"{symbol} unfilled after {FILL_TIMEOUT_S}s — abandoning "\n                            "(check the broker: a late fill would be an untracked position)", "critical")\n                return None\n        else:\n            if not ltp or float(ltp) <= 0:\n                self._alert("NO_QUOTE", f"{symbol}: no LTP for the paper fill — entry forfeited", "error")\n                return None\n            fill_px = float(ltp)\n        fill_px = round(fill_px, 2)\n        sl, tp = levels_for(fill_px, sl_pts, tp_pts)\n        entry_ts = int(self.clock())\n        pid = None\n        if insert_paper_trade is not None:\n            try:\n                pid = str(uuid.uuid4())\n                insert_paper_trade(\n                    paper_trade_id=pid, strategy_name=STRATEGY_ID, trade_mode=mode,\n                    symbol=symbol, token=int(token or 0), side=side, entry_price=fill_px,\n                    candle_ts=int(decision_ts), sl_price=float(sl or 0.0), tp_price=float(tp or 0.0),\n                    rr=round(tp_pts / sl_pts, 2) if sl_pts > 0 and tp_pts > 0 else 0.0,\n                    lots=lots, lot_size=lot_size, qty=qty, trade_direction="LONG", group_id="EMC",\n                    trade_class=None)\n            except Exception as e:\n                self._alert("ROW_FAIL", f"{symbol}: {e!r}"\n                            + (" — POSITION OPEN AT BROKER, row missing" if mode == "LIVE" else ""),\n                            "critical" if mode == "LIVE" else "error")\n                pid = None\n        self.pos = EmcPosition(row_id=pid, symbol=symbol, token=int(token or 0), side=side, entry_px=fill_px,\n                               qty=qty, lots=lots, mode=mode, sl=sl, tp=tp, entry_ts=entry_ts,\n                               decision_ts=int(decision_ts), entry_spot=entry_spot, mark=fill_px)\n        self.day_stats["entries"] += 1\n        write_audit_log(f"[EMC][ENTRY][{mode}] {side} {symbol} @ {fill_px} SL={sl} TP={tp} qty={qty} {note}")\n        self._notify("notify_trade_entry", {\n            "strategy_id": STRATEGY_ID, "mode": mode, "symbol": symbol, "side": side,\n            "entry_price": fill_px, "quantity": qty, "sl": sl, "tp": tp,\n            "note": f"Ember {side} · NIFTY 5m EMA cross + option EMA aligned · SL −{sl_pts:g} / TP +{tp_pts:g} "\n                    f"premium pts · {note}".strip()})\n        return fill_px\n\n    # ── intraminute exits ──\n    def check_exits(self, ltp: Optional[float]) -> Optional[str]:\n        """Called on every poll with the held option\'s LTP. Stop before target\n        (backtest order). Returns the exit reason when the position closed."""\n        pos = self.pos\n        if pos is None or not ltp or float(ltp) <= 0:\n            return None\n        ltp = float(ltp)\n        pos.mark = ltp\n        reason = None\n        if pos.sl is not None and ltp <= pos.sl:\n            reason = "SL"\n        elif pos.tp is not None and ltp >= pos.tp:\n            reason = "TP"\n        if reason is None:\n            return None\n        return reason if self.close_trade(reason=reason, ltp=ltp) is not None else None\n\n    # ── exits ──\n    def close_trade(self, *, reason: str, ltp: Optional[float] = None, notify_core: bool = True) -> Optional[float]:\n        """Close the open position. Returns the exit price, or None when\n        nothing was closed (no position, or LIVE backoff — retried later)."""\n        pos = self.pos\n        if pos is None:\n            return None\n        px = float(ltp if ltp else (pos.mark or pos.entry_px))\n        if pos.mode == "LIVE" and self.executor is not None:\n            if self.clock() < self._close_backoff_until:\n                return None\n            probe = getattr(self.executor, "get_open_positions_or_none", None)\n            if callable(probe):\n                try:\n                    positions = probe()\n                except Exception:\n                    positions = None\n                if positions is None:\n                    self._close_backoff_n += 1\n                    self._close_backoff_until = self.clock() + min(60.0, 5.0 * self._close_backoff_n)\n                    self._alert("BROKER_UNREADABLE", f"{pos.symbol}: holdings read failed — NO order placed, "\n                                f"backoff {min(60, 5 * self._close_backoff_n)}s", "error")\n                    return None\n                holding = any((p.get("tradingsymbol") or p.get("symbol")) == pos.symbol\n                              and int(p.get("quantity") or p.get("qty") or 0) > 0 for p in positions)\n                if not holding:\n                    self._alert("BROKER_FLAT", f"{pos.symbol}: broker shows no holding — closing the ROW only, "\n                                "placing NOTHING (reconcile-first)", "warning")\n                    return self._finish_close(pos, px, "BROKER_FLAT" if reason != "XOVER" else reason,\n                                              notify_core)\n            self._close_backoff_n = 0\n            try:\n                order_id = self.executor.place_market_sell(pos.symbol, pos.qty)\n                t0 = self.clock()\n                while self.clock() - t0 < FILL_TIMEOUT_S:\n                    try:\n                        st = self.executor.get_order_fill(order_id)\n                    except Exception:\n                        self.sleep(FILL_POLL_S)\n                        continue\n                    if (st or {}).get("status") == "COMPLETE":\n                        px = float(st.get("avg_price") or px)\n                        break\n                    self.sleep(FILL_POLL_S)\n            except Exception as e:\n                self._alert("SELL_FAIL", f"{pos.symbol}: {e!r} — POSITION MAY BE OPEN AT THE BROKER", "critical")\n        return self._finish_close(pos, px, reason, notify_core)\n\n    def _finish_close(self, pos, px: float, reason: str, notify_core: bool) -> float:\n        px = round(float(px), 2)\n        if close_paper_trade is not None and pos.row_id:\n            try:\n                close_paper_trade(paper_trade_id=pos.row_id, exit_price=px, exit_reason=reason)\n            except Exception as e:\n                self._alert("CLOSE_ROW_FAIL", f"{pos.symbol}: {e!r}", "error")\n        self.day_stats["exits"][reason] = self.day_stats["exits"].get(reason, 0) + 1\n        gross = (px - pos.entry_px) * pos.qty\n        write_audit_log(f"[EMC][EXIT][{pos.mode}] {reason} {pos.symbol} @ {px} gross={gross:,.0f}")\n        fn = {"SL": "notify_sl_exit", "TP": "notify_tp_exit"}.get(reason, "notify_manual_exit")\n        self._notify(fn, {"strategy_id": STRATEGY_ID, "mode": pos.mode, "symbol": pos.symbol, "side": pos.side,\n                          "entry_price": pos.entry_px, "exit_price": px, "quantity": pos.qty,\n                          "pnl": round(gross, 2), "exit_reason": reason, "reason": reason})\n        self.last_closed_qty = pos.qty\n        self.pos = None\n        if notify_core and self.on_closed is not None:\n            try:\n                self.on_closed(int(self.clock()), px, reason)\n            except Exception as e:\n                write_audit_log(f"[EMC][CORE_CLOSE_HOOK_FAIL] {e!r}")\n        return px\n\n    # ── restart ──\n    def today_rows(self, day_start: int, rows=None) -> list:\n        """Today\'s EMC rows (twins excluded), oldest first. rows= for tests."""\n        if rows is None:\n            if get_conn is None:\n                return []\n            cur = get_conn().execute(\n                "SELECT paper_trade_id, symbol, token, side, entry_price, exit_price, exit_reason, qty, lots,"\n                " trade_mode, sl_price, tp_price, candle_ts FROM paper_trades WHERE strategy_name=?"\n                " AND candle_ts >= ? AND paper_trade_id NOT LIKE \'SHD:%\' ORDER BY candle_ts",\n                (STRATEGY_ID, int(day_start)))\n            rows = [dict(zip([c[0] for c in cur.description], r)) for r in cur.fetchall()]\n        return [r for r in rows if not str(r.get("paper_trade_id") or "").startswith("SHD:")]\n\n    def open_rows_any_day(self) -> list:\n        if get_conn is None:\n            return []\n        cur = get_conn().execute(\n            "SELECT paper_trade_id, symbol, token, side, entry_price, qty, lots, trade_mode, sl_price, tp_price,"\n            " candle_ts FROM paper_trades WHERE strategy_name=? AND exit_price IS NULL"\n            " AND paper_trade_id NOT LIKE \'SHD:%\' ORDER BY candle_ts", (STRATEGY_ID,))\n        return [dict(zip([c[0] for c in cur.description], r)) for r in cur.fetchall()]\n\n    def resume_row(self, r: dict) -> None:\n        self.pos = EmcPosition(\n            row_id=r.get("paper_trade_id"), symbol=r["symbol"], token=int(r.get("token") or 0), side=r["side"],\n            entry_px=float(r["entry_price"]), qty=int(r["qty"]), lots=int(r.get("lots") or 1),\n            mode=str(r.get("trade_mode") or "PAPER").upper(),\n            sl=(float(r["sl_price"]) if r.get("sl_price") else None),\n            tp=(float(r["tp_price"]) if r.get("tp_price") else None),\n            entry_ts=int(r.get("candle_ts") or 0), decision_ts=int(r.get("candle_ts") or 0),\n            entry_spot=None, mark=float(r["entry_price"]))\n        write_audit_log(f"[EMC][RESUME] open {self.pos.side} {self.pos.symbol} @ {self.pos.entry_px} "\n                        f"({self.pos.mode}) SL={self.pos.sl} TP={self.pos.tp}")\n\n    def mark_stale(self, r: dict, why: str) -> None:\n        """A prior-day OPEN row (intraday strategy → the app died before its\n        own EOD). Closed at its entry price with reason STALE — never adopted,\n        never traded. LIVE: the broker\'s MIS auto-square has normally flattened\n        it; the critical alert says to verify."""\n        rid = r.get("paper_trade_id")\n        if close_paper_trade is not None and rid:\n            try:\n                close_paper_trade(paper_trade_id=rid, exit_price=float(r["entry_price"]), exit_reason="STALE")\n            except Exception as e:\n                self._alert("STALE_FAIL", f"{rid}: {e!r}", "error")\n        self._alert("STALE_ROW", f"{r.get(\'symbol\')} ({r.get(\'trade_mode\')}) open since a prior day — closed as "\n                    f"STALE at entry; {why}. VERIFY THE BROKER BOOK.", "critical")\n\n    def eod_squareoff(self, ltp: Optional[float] = None) -> int:\n        return 1 if self.close_trade(reason="EOD", ltp=ltp) is not None else 0\n\n    def kill_all(self) -> int:\n        n = 1 if self.close_trade(reason="KILL", ltp=None) is not None else 0\n        write_audit_log(f"[EMC][KILL] flattened {n} position(s)")\n        return n\n\n    def kill_adapter(self) -> dict:\n        """kill_switch contract: {"closed", "remaining", "detail"}."""\n        n = self.kill_all()\n        return {"closed": n, "remaining": 0 if self.pos is None else 1,\n                "detail": [f"EMC_V1 closed {n}"] + ([f"still open: {self.pos.symbol}"] if self.pos else [])}\n\n    def state(self) -> dict:\n        p = self.pos\n        return {"strategy": STRATEGY_ID, "mode": self.mode(),\n                "position": None if p is None else {\n                    "symbol": p.symbol, "side": p.side, "mode": p.mode, "entry": p.entry_px, "qty": p.qty,\n                    "lots": p.lots, "sl": p.sl, "tp": p.tp, "entry_ts": p.entry_ts, "mark": p.mark,\n                    "row_id": p.row_id},\n                "day": dict(self.day_stats)}\n'

NEW_FILES['backend/app/engine/emc/emc_engine.py'] = '# backend/app/engine/emc/emc_engine.py\n#\n# ── EMC_V1 ENGINE ── live day loop for "Ember". Fence: EMC_V1_LIVE_20261011\n#\n# Shape: OrbEngine\'s (own daemon thread, REST only — NO new KiteTicker; the\n# fleet is already over Kite\'s socket budget), with the decision taken by the\n# backtest\'s own EmcDayCore and the indicators re-computed by the backtest\'s\n# own functions (emc_live_core). One tick() per second does, in order:\n#\n#   1. intraminute exits — while a position is open, quote the held option\n#      and let the manager take SL / TP at market (paper: at that LTP);\n#   2. EOD — at the square-off minute flatten, then end the session in the\n#      core (expire any pending setup);\n#   3. decisions — every COMPLETED minute k, strictly in order, never skipped:\n#      freeze kite-historical 1m spot candles (exchange-true bars, the source\n#      the backtest corpus is built from) → recompute spot crosses → refresh\n#      the pending setup\'s option candles → EmcDayCore.on_minute_close(k, x).\n#      Selection reads a fresh weekly-chain snapshot; the entry is a market\n#      buy (paper: a fresh LTP) right after minute k closes — the backtest\'s\n#      "next minute open" model.\n#\n# Fail-closed rules (each one alerts):\n#   * short spot warm-up / config the runner rejects / unsupported live knob\n#     → the DAY is refused (an adopted open position is still managed);\n#   * a restated spot cross → FROZEN (no new setups; position managed by\n#     SL / TP / EOD only);\n#   * a decision processed more than LATE_S after its minute closed (data\n#     stall, restart) → no entry and no selection on that minute;\n#   * a pending setup is NOT resurrected after a restart (its chain snapshot\n#     is gone) — an open position IS (adopted from paper_trades).\n\nfrom __future__ import annotations\n\nimport threading\nimport time\nfrom datetime import date, datetime, timedelta\nfrom typing import Callable, Dict, List, Optional, Tuple\n\nfrom app.event_bus.audit_logger import write_audit_log\nfrom app.backtest.emc.emc_v1_engine import EmcDayCore, DayTrade, SESSION_OPEN_MIN\nfrom app.engine.emc.emc_live_core import (LiveSpotCrosses, LiveOptionTrack, live_params,\n                                          option_warm_from_sessions, day_start_epoch_of, minute_of)\nfrom app.engine.emc.emc_manager import EmcManager\n\nIST = 5 * 3600 + 30 * 60\nSPOT_TOKEN = 256265                  # NSE:NIFTY 50\nSETTLE_S = 3                         # let the minute\'s candle publish before reading it\nSPOT_WAIT_S = 90                     # give up waiting for one missing spot minute\nLATE_S = 60                          # a decision older than this never opens a trade\nBOOT_RETRY_S = 60\nEXIT_POLL_S = 2                      # SL/TP quote cadence while a position is open (Kite quote budget)\n\n\ndef _naive_ist(ts: int) -> datetime:\n    return datetime.utcfromtimestamp(int(ts) + IST)\n\n\nclass EmcFeed:\n    """All broker data access (injectable for tests)."""\n\n    def __init__(self, kite_fn: Callable, chain_fn: Optional[Callable] = None):\n        self.kite_fn = kite_fn\n        self.chain_fn = chain_fn\n\n    def kite(self):\n        try:\n            return self.kite_fn()\n        except Exception:\n            return None\n\n    def _hist(self, token: int, frm: datetime, to: datetime, interval: str = "minute") -> List[dict]:\n        k = self.kite()\n        if k is None:\n            raise RuntimeError("data kite unavailable")\n        rows = k.historical_data(instrument_token=int(token), from_date=frm, to_date=to, interval=interval) or []\n        out = []\n        for r in rows:\n            d = r["date"]\n            ts = int(d.timestamp()) if hasattr(d, "timestamp") else int(d)\n            out.append({"ts": ts - ts % 60, "open": float(r["open"]), "high": float(r["high"]),\n                        "low": float(r["low"]), "close": float(r["close"])})\n        out.sort(key=lambda c: c["ts"])\n        return out\n\n    def prior_days(self, today: date, n: int) -> List[date]:\n        k = self.kite()\n        if k is None:\n            return []\n        rows = k.historical_data(instrument_token=SPOT_TOKEN, from_date=today - timedelta(days=30),\n                                 to_date=today - timedelta(days=1), interval="day") or []\n        days = sorted({(r["date"].date() if hasattr(r["date"], "date") else r["date"]) for r in rows})\n        days = [d for d in days if d < today]\n        return days[-n:] if n else days\n\n    def sessions(self, token: int, days: List[date]) -> List[Tuple[int, List[dict]]]:\n        """[(day_start_epoch, candles)] for exactly `days` (one call)."""\n        if not days:\n            return []\n        frm = datetime(days[0].year, days[0].month, days[0].day, 9, 0)\n        to = datetime(days[-1].year, days[-1].month, days[-1].day, 15, 45)\n        rows = self._hist(token, frm, to)\n        want = {int((datetime(d.year, d.month, d.day) - datetime(1970, 1, 1)).total_seconds()) - IST for d in days}\n        by: Dict[int, List[dict]] = {}\n        for c in rows:\n            ds = day_start_epoch_of(c["ts"])\n            if ds in want:\n                by.setdefault(ds, []).append(c)\n        return [(ds, by[ds]) for ds in sorted(by)]\n\n    def today_completed(self, token: int, now: int) -> List[dict]:\n        ds = day_start_epoch_of(now)\n        frm = _naive_ist(ds + SESSION_OPEN_MIN * 60)\n        rows = self._hist(token, frm, _naive_ist(now))\n        return [c for c in rows if c["ts"] + 60 <= now and day_start_epoch_of(c["ts"]) == ds]\n\n    def chain(self):\n        if self.chain_fn is not None:\n            return self.chain_fn()\n        from app.engine.ic.ic_selection import snapshot_weekly_chain\n        k = self.kite()\n        if k is None:\n            return None, [], {}\n        return snapshot_weekly_chain(k, getattr(k, "api_key", None), getattr(k, "access_token", None))\n\n    def quote(self, symbols: List[str]) -> Dict[str, float]:\n        k = self.kite()\n        if k is None or not symbols:\n            return {}\n        q = k.quote([f"NFO:{s}" for s in symbols]) or {}\n        out = {s: float((q.get(f"NFO:{s}") or {}).get("last_price") or 0) for s in symbols}\n        try:\n            from app.marketdata.ltp_store import LTPStore\n            for s, v in out.items():\n                if v > 0:\n                    LTPStore.update(s, v)\n        except Exception:\n            pass\n        return out\n\n\nclass EmcEngine:\n    def __init__(self, manager: EmcManager, broker_manager=None, *, feed: Optional[EmcFeed] = None,\n                 clock: Callable[[], float] = time.time, sleep: Callable[[float], None] = time.sleep,\n                 trading_day_fn: Optional[Callable[[date], bool]] = None,\n                 expected_expiry_fn: Optional[Callable[[date], date]] = None):\n        self.gm = manager\n        self.broker = broker_manager\n        self.feed = feed or EmcFeed(lambda: broker_manager.get_data_kite())\n        self.clock, self.sleep = clock, sleep\n        self.trading_day_fn = trading_day_fn\n        self.expected_expiry_fn = expected_expiry_fn\n        self._running = False\n        self._thread: Optional[threading.Thread] = None\n        self.gm.on_closed = self._on_manager_close\n        self._reset_day(None)\n        self.last_poll_ts: Optional[int] = None\n\n    # ── day state ──\n    def _reset_day(self, day: Optional[date]):\n        self.day = day\n        self.ds: Optional[int] = None\n        self.ready = False\n        self.refused: Optional[str] = None\n        self.params = None\n        self.mcfg: dict = {}\n        self.spot: Optional[LiveSpotCrosses] = None\n        self.core: Optional[EmcDayCore] = None\n        self.diag: dict = {}\n        self.next_k = SESSION_OPEN_MIN\n        self.finished = False\n        self.prior_days: List[date] = []\n        self.tracks: Dict[str, LiveOptionTrack] = {}\n        self.chain_cache: Dict[int, tuple] = {}\n        self.meta: Dict[str, dict] = {}\n        self.pending_exit: Optional[str] = None\n        self.boot_attempts = 0\n        self.boot_last_try = 0.0\n        self.boot_alerted = False\n        self.alerted: set = set()\n        self.now_i = 0\n        self.last_cross: Optional[Tuple[int, int]] = None\n        self.dte: Optional[int] = None\n        self.dte_tag = "base"\n        self._last_exit_poll = 0\n\n    def _alert_once(self, key: str, code: str, msg: str, severity: str = "warning"):\n        if key in self.alerted:\n            return\n        self.alerted.add(key)\n        self.gm._alert(code, msg, severity)\n\n    def _is_trading_day(self, d: date) -> bool:\n        if d.weekday() >= 5:\n            return False\n        try:\n            if self.trading_day_fn is not None:\n                return bool(self.trading_day_fn(d))\n            from app.utils.market_hours import is_trading_day\n            return bool(is_trading_day(d))\n        except Exception:\n            return True\n\n    def _expected_expiry(self, d: date) -> date:\n        if self.expected_expiry_fn is not None:\n            return self.expected_expiry_fn(d)\n        from app.backtest.engine.expiry_calendar import expected_expiry_for_day\n        return expected_expiry_for_day(d)\n\n    # ── thread ──\n    def start(self):\n        if self._running:\n            return\n        self._running = True\n        self._thread = threading.Thread(target=self._loop, name="emc_v1_engine", daemon=True)\n        self._thread.start()\n\n    def stop(self):\n        self._running = False\n\n    def _loop(self):\n        write_audit_log("[EMC][ENGINE] loop up")\n        while self._running:\n            try:\n                self.tick(self.clock())\n            except Exception as e:\n                write_audit_log(f"[EMC][ENGINE][ERR] {e!r}")\n            self.sleep(1.0)\n        write_audit_log("[EMC][ENGINE] loop down")\n\n    # ── one step ──\n    def tick(self, now: float) -> None:\n        now_i = int(now)\n        self.now_i = now_i\n        self.last_poll_ts = now_i\n        d = _naive_ist(now_i).date()\n        hm = minute_of(now_i)\n        if not self._is_trading_day(d) or hm < 9 * 60 + 5 or hm > 15 * 60 + 31:\n            return\n        if self.day != d:\n            self._reset_day(d)\n            self.ds = day_start_epoch_of(now_i)\n        if not self.ready:\n            self._try_boot(now_i)\n        # 1 ── intraminute exits (also retries a deferred XOVER)\n        if self.gm.pos is not None and now_i - self._last_exit_poll >= EXIT_POLL_S:\n            self._last_exit_poll = now_i\n            if self.pending_exit and self.gm.close_trade(reason=self.pending_exit,\n                                                       ltp=self._ltp(self.gm.pos.symbol)) is not None:\n                self.pending_exit = None\n            elif self.gm.pos is not None:\n                self.gm.check_exits(self._ltp(self.gm.pos.symbol))\n        # 2 ── EOD (also on a refused day that adopted an open position)\n        eod_min = self.params.eod_min if self.params is not None else 15 * 60 + 15\n        if hm >= eod_min:\n            if self.gm.pos is not None:\n                self.gm.close_trade(reason="EOD", ltp=self._ltp(self.gm.pos.symbol))\n            if self.gm.pos is None and not self.finished and self.core is not None:\n                self.core.finish(None)\n                self.finished = True\n                write_audit_log(f"[EMC][DAY] done — entries {self.core.day_entries} losses "\n                                f"{self.core.day_losses} diag {self.diag}")\n            return\n        if not self.ready:\n            return\n        # 3 ── decisions, completed minutes in order\n        last_done = hm - 1\n        while self.next_k <= min(last_done, self.params.eod_min - 1):\n            if now_i < self._boundary(self.next_k) + SETTLE_S:\n                break\n            if not self._process_minute(self.next_k, now_i):\n                break\n            self.next_k += 1\n\n    def _boundary(self, k: int) -> int:\n        """Epoch at which minute k has closed."""\n        return self.ds + (k + 1) * 60\n\n    def _ltp(self, sym: str) -> Optional[float]:\n        try:\n            return self.feed.quote([sym]).get(sym) or None\n        except Exception:\n            return None\n\n    # ── boot: config, warm-up, restart restore, backfill ──\n    def _try_boot(self, now_i: int) -> None:\n        if self.refused:\n            return\n        if self.boot_attempts and now_i - self.boot_last_try < BOOT_RETRY_S:\n            return\n        self.boot_attempts += 1\n        self.boot_last_try = now_i\n        hm = minute_of(now_i)\n        cfg = self.gm.cfg() or {}\n        if not cfg:\n            return self._refuse("CFG_MISSING", "strategy config empty — loader path broken?", "critical")\n        p, m, bad = live_params(cfg)\n        if bad:\n            return self._refuse("CFG_REFUSED", bad, "critical")\n        # DTE × lots / skip-expiry — read once per session (ORB/VET convention)\n        try:\n            from app.engine.dte_live import resolve_day_lots\n            lots, self.dte, self.dte_tag = resolve_day_lots(m, int(m.get("lots") or 1), self.day, "[EMC]")\n        except Exception:\n            lots, self.dte, self.dte_tag = int(m.get("lots") or 1), None, "unknown"\n        if self.dte_tag == "skip":\n            return self._refuse("DTE_SKIP", f"today is {self.dte}DTE — no EMC trading (dte_lot_mult)", "info")\n        self.gm.day_lots = int(lots) if self.dte_tag == "scaled" else None\n        if m.get("skip_expiry_day") and self._expected_expiry(self.day) == self.day:\n            return self._refuse("EXPIRY_SKIP", "expiry day — skip_expiry_day is ON", "info")\n        try:\n            if not self.prior_days:\n                self.prior_days = self.feed.prior_days(self.day, 12)\n            need = int(m["warmup_sessions"])\n            warm_days = self.prior_days[-need:]\n            warm = self.feed.sessions(SPOT_TOKEN, warm_days)\n        except Exception as e:\n            warm, need = [], int(m.get("warmup_sessions") or 5)\n            write_audit_log(f"[EMC][BOOT] warm-up fetch failed: {e!r}")\n        spot = LiveSpotCrosses(fast=m["ema_fast"], slow=m["ema_slow"], tf=m["spot_tf"],\n                               warm_sessions_1m=[c for _, c in warm], need_sessions=need,\n                               first_candle_cross=m["first_candle_cross"])\n        if not spot.warmup_ok():\n            msg = f"spot warm-up {len(spot.warm_sessions)}/{need} sessions (attempt {self.boot_attempts})"\n            write_audit_log(f"[EMC][BOOT] {msg} — retrying every {BOOT_RETRY_S}s")\n            if hm >= 9 * 60 + 20 and not self.boot_alerted:\n                self.boot_alerted = True\n                self.gm._alert("WARMUP", f"{msg} at 09:20 — EMC is blind until it loads", "error")\n            if hm >= 15 * 60:\n                self._refuse("NO_WARMUP", "no spot warm-up by 15:00 — not trading today", "error")\n            return\n        self.params, self.mcfg, self.spot = p, m, spot\n        self.diag = {}\n        self.core = EmcDayCore(p=p, quotes_at=self._quotes_at, track_of=self._track_of, spot_at=self._spot_at,\n                               net_of=self._net_of, fill_entry=self._fill_entry, fill_exit=self._fill_exit,\n                               diag=self.diag)\n        self._restore(now_i)\n        # backfill today\'s completed minutes WITHOUT decisions\n        try:\n            for c in self.feed.today_completed(SPOT_TOKEN, now_i):\n                self.spot.add(c)\n        except Exception as e:\n            write_audit_log(f"[EMC][BOOT] backfill failed: {e!r} — decisions start as minutes arrive")\n        if self.spot.today:\n            self.spot.recompute()                      # seeds the prefix guard\n            self.next_k = (self.spot.last_minute() or SESSION_OPEN_MIN) + 1\n            write_audit_log(f"[EMC][BOOT] backfilled {len(self.spot.today)} spot minutes — decisions resume at "\n                            f"{self.next_k // 60:02d}:{self.next_k % 60:02d} (earlier crosses are NOT traded)")\n        else:\n            self.next_k = SESSION_OPEN_MIN\n        self.ready = True\n        write_audit_log(f"[EMC][BOOT] armed: mode={self.gm.mode()} lots={self.gm.qty()[0]} ({self.dte_tag}"\n                        f"{\'\' if self.dte is None else f\', {self.dte}DTE\'}) EMA{m[\'ema_fast\']}/{m[\'ema_slow\']} "\n                        f"band ₹{m[\'sel_prem_min\']:g}-{m[\'sel_prem_max\']:g} SL {m[\'sl_pts\']:g} TP {m[\'tp_pts\']:g} "\n                        f"cutoff {m[\'entry_cutoff\']} EOD {m[\'eod_square_off\']} loss-cap {m[\'max_losses_per_day\']} "\n                        f"no-arm {m.get(\'arm_skip_from\') or \'-\'}–{m.get(\'arm_skip_to\') or \'-\'}")\n\n    def _refuse(self, code: str, msg: str, severity: str) -> None:\n        self.refused = f"{code}: {msg}"\n        self.gm.day_stats["refused"] = self.refused\n        self.gm._alert(code, f"day refused — {msg}", severity)\n        # an open position from before still needs managing\n        try:\n            if self.gm.pos is None:\n                for r in self.gm.open_rows_any_day():\n                    if day_start_epoch_of(int(r.get("candle_ts") or 0)) == day_start_epoch_of(self.now_i):\n                        self.gm.resume_row(r)\n                        break\n        except Exception:\n            pass\n\n    def _restore(self, now_i: int) -> None:\n        """Restart: stale prior-day rows, today\'s counters, today\'s open row."""\n        ds = self.ds\n        try:\n            for r in self.gm.open_rows_any_day():\n                if day_start_epoch_of(int(r.get("candle_ts") or 0)) != ds:\n                    self.gm.mark_stale(r, "intraday strategy, crash before EOD")\n            rows = self.gm.today_rows(ds)\n        except Exception as e:\n            self.gm._alert("RESUME_FAIL", f"{e!r} — day budget starts at 0", "error")\n            return\n        losses = 0\n        open_row = None\n        for r in rows:\n            if r.get("exit_price") is None:\n                open_row = r\n                continue\n            if self.gm.net_of(r["entry_price"], r["exit_price"], int(r["qty"])) < 0:\n                losses += 1\n        c = self.core\n        c.day_entries = len(rows)\n        c.day_losses = losses\n        if c.p.max_losses and losses >= c.p.max_losses:\n            c.halted = True\n        self.gm.day_stats["entries"] = len(rows)\n        if open_row is not None and self.gm.pos is None:\n            self.gm.resume_row(open_row)\n        if self.gm.pos is not None:\n            pos = self.gm.pos\n            t = DayTrade(side=pos.side, sym=pos.symbol, strike=None, sel_min=minute_of(pos.decision_ts or now_i),\n                         sel_px=pos.entry_px, entry_min=minute_of(pos.entry_ts or now_i), entry_px=pos.entry_px,\n                         sl=pos.sl, tp=pos.tp)\n            c.adopt_position(t, check_from=minute_of(now_i))\n        if rows:\n            write_audit_log(f"[EMC][RESUME] today: {len(rows)} entries, {losses} losing closed"\n                            f"{\', HALTED\' if c.halted else \'\'}{\', 1 open\' if self.gm.pos else \'\'} "\n                            "(a pending setup is never resurrected)")\n\n    # ── per minute ──\n    def _process_minute(self, k: int, now_i: int) -> bool:\n        sp = self.spot\n        if (sp.last_minute() or -1) < k:\n            try:\n                for c in self.feed.today_completed(SPOT_TOKEN, now_i):\n                    sp.add(c)\n            except Exception as e:\n                self._alert_once(f"spotfetch{k // 15}", "SPOT_FETCH", f"{e!r}", "error")\n            if (sp.last_minute() or -1) < k:\n                if now_i - self._boundary(k) < SPOT_WAIT_S:\n                    return False                      # not published yet — wait\n                self._alert_once(f"spotmiss{k}", "SPOT_MISSING",\n                                 f"no spot candle for {k // 60:02d}:{k % 60:02d} after {SPOT_WAIT_S}s — "\n                                 "decisions are delayed until data resumes", "error")\n                return False\n        crosses = sp.recompute()\n        if sp.guard.frozen:\n            self._alert_once("frozen", "FROZEN", f"{sp.guard.reason} — no new setups today; an open position "\n                             "is managed by SL / TP / EOD only", "critical")\n            return True\n        x = crosses.get(k, 0)\n        if x:\n            self.last_cross = (k, x)\n            write_audit_log(f"[EMC][CROSS] {\'UP\' if x > 0 else \'DOWN\'} on the {k // 60:02d}:{k % 60:02d} close"\n                            f"{\' (first candle / overnight gap)\' if sp.gap_cross_min == k else \'\'}")\n        c = self.core\n        if c.setup is not None:\n            self._feed_track(c.setup["track"], c.setup["c"]["sym"], now_i)\n        c.on_minute_close(k, x)\n        return True\n\n    # ── core callbacks ──\n    def _late(self, k: int) -> bool:\n        return self.now_i - self._boundary(k) > LATE_S\n\n    def _quotes_at(self, k: int, side: str) -> List[dict]:\n        if self._late(k):\n            self._alert_once(f"latesel{k}", "LATE_DECISION",\n                             f"{side} cross on {k // 60:02d}:{k % 60:02d} processed "\n                             f"{self.now_i - self._boundary(k)}s late — no selection", "warning")\n            return []\n        if k not in self.chain_cache:\n            try:\n                self.chain_cache = {k: self.feed.chain()}\n            except Exception as e:\n                self.gm._alert("CHAIN_FAIL", f"{e!r} — setup forfeited", "error")\n                return []\n        expiry, rows, ltp = self.chain_cache[k]\n        if not rows:\n            self.gm._alert("CHAIN_FAIL", "empty weekly chain snapshot — setup forfeited", "error")\n            return []\n        want = self._expected_expiry(self.day)\n        if expiry is not None and expiry != want:\n            self._alert_once("expirymm", "EXPIRY_MISMATCH",\n                             f"nearest listed expiry {expiry} ≠ calendar {want} — using the listed one", "warning")\n        out = []\n        for r in rows:\n            sym = str(r.get("tradingsymbol") or "")\n            if (r.get("instrument_type") or ("CE" if sym.endswith("CE") else "PE")) != side:\n                continue\n            px = float((ltp or {}).get(sym) or 0)\n            if px <= 0 or r.get("strike") is None:\n                continue\n            self.meta[sym] = {"token": int(r.get("instrument_token") or r.get("token") or 0),\n                              "strike": float(r["strike"]), "expiry": expiry}\n            out.append({"sym": sym, "strike": float(r["strike"]), "price": px})\n        return out\n\n    def _track_of(self, c: dict) -> LiveOptionTrack:\n        sym = c["sym"]\n        tr = self.tracks.get(sym)\n        if tr is None:\n            meta = self.meta.get(sym, {})\n            token, expiry = meta.get("token"), meta.get("expiry")\n            m = self.mcfg\n            n = int(m.get("opt_warmup_sessions") or 0)\n            # runner R3 parity: only sessions on which this contract was the\n            # expected weekly (the corpus holds front-week contracts only)\n            days = [d for d in self.prior_days if expiry is None or self._expected_expiry(d) == expiry][-n:] if n else []\n            warm = []\n            try:\n                warm = option_warm_from_sessions(self.feed.sessions(token, days), m["opt_tf"]) if days else []\n            except Exception as e:\n                write_audit_log(f"[EMC][OPT_WARM] {sym}: {e!r} — EMAs start cold")\n            tr = LiveOptionTrack(fast=m["ema_fast"], slow=m["ema_slow"], tf=m["opt_tf"], ds=self.ds, warm_bars=warm)\n            self.tracks[sym] = tr\n            self.diag["opt_tracks"] = self.diag.get("opt_tracks", 0) + 1\n            if not warm:\n                self.diag["opt_tracks_cold"] = self.diag.get("opt_tracks_cold", 0) + 1\n            write_audit_log(f"[EMC][SETUP] {sym} ₹{c[\'price\']:g} selected — option warm bars {len(warm)} "\n                            f"from {len(days)} session(s)")\n        self._feed_track(tr, sym, self.now_i)\n        return tr\n\n    def _feed_track(self, tr: LiveOptionTrack, sym: str, now_i: int) -> None:\n        token = (self.meta.get(sym) or {}).get("token")\n        if not token:\n            return\n        try:\n            for cndl in self.feed.today_completed(token, now_i):\n                tr.add(cndl)\n        except Exception as e:\n            self._alert_once(f"optfetch{sym}{now_i // 300}", "OPT_FETCH", f"{sym}: {e!r}", "warning")\n\n    def _spot_at(self, k: int) -> Optional[float]:\n        for b in reversed(self.spot.today if self.spot else []):\n            if minute_of(b.ts) <= k:\n                return float(b.close)\n        return None\n\n    def _net_of(self, entry: float, exit_px: float) -> float:\n        g = self.gm\n        q = g.pos.qty if g.pos is not None else getattr(g, "last_closed_qty", None)\n        return g.net_of(entry, exit_px, qty=q)\n\n    def _fill_entry(self, sym: str, k: int):\n        if self._late(k):\n            self._alert_once(f"lateentry{k}", "LATE_DECISION", f"{sym}: trigger on {k // 60:02d}:{k % 60:02d} "\n                             f"processed {self.now_i - self._boundary(k)}s late — entry forfeited", "warning")\n            return None, k\n        setup = self.core.setup\n        meta = self.meta.get(sym) or {}\n        ltp = self._ltp(sym)\n        m = self.mcfg\n        sk = int(setup["k"])\n        wait_txt = " (already aligned)" if k == sk else f", waited {k - sk}m"\n        note = f"armed {sk // 60:02d}:{sk % 60:02d} at ₹{float(setup[\'c\'][\'price\']):g}{wait_txt}"\n        px = self.gm.open_trade(symbol=sym, token=meta.get("token") or 0, side=setup["side"], ltp=ltp,\n                                entry_spot=self._spot_at(k), decision_ts=self._boundary(k),\n                                sl_pts=float(m["sl_pts"]), tp_pts=float(m["tp_pts"]), note=note)\n        if px is None:\n            return None, k\n        return px, k + 1\n\n    def _fill_exit(self, sym: str, k: int, last):\n        px = self.gm.close_trade(reason="XOVER", ltp=self._ltp(sym), notify_core=False)\n        if px is None and self.gm.pos is not None:\n            self.pending_exit = "XOVER"                 # LIVE backoff — retried every tick\n            return None, k\n        return px, k + 1\n\n    def _on_manager_close(self, ts: int, px: float, reason: str) -> None:\n        if self.core is None or self.core.pos is None:\n            return\n        k = min(minute_of(ts), self.params.eod_min) if self.params else minute_of(ts)\n        self.core.external_close(k, px, reason)\n\n    # ── panel ──\n    def phase(self) -> str:\n        if self.day is None:\n            return "PRE_OPEN"\n        if self.refused and self.gm.pos is None:\n            return "REFUSED"\n        if not self.ready:\n            return "BOOTING"\n        if self.spot and self.spot.guard.frozen:\n            return "FROZEN"\n        if self.gm.pos is not None:\n            return "IN_POSITION"\n        if self.finished:\n            return "DONE"\n        hm = minute_of(self.now_i)\n        if self.core and self.core.halted:\n            return "HALTED"\n        if self.core and self.core.setup is not None:\n            return "SETUP_PENDING"\n        if hm >= self.params.block_min:\n            return "NO_NEW_ENTRIES"\n        return "WAITING_CROSS"\n'

NEW_FILES['backend/app/engine/emc/emc_runtime.py'] = '# backend/app/engine/emc/emc_runtime.py\n#\n# ── EMC_V1 RUNTIME ── async entrypoint (ORB/BRK pattern). Fence: EMC_V1_LIVE_20261011\n# Never raises out; kill adapter registered at boot; executor re-attach loop.\n# Restart restore (open row, day counters) happens inside the engine\'s boot,\n# after the day\'s config is read.\n\nfrom __future__ import annotations\n\nimport asyncio\nfrom typing import Optional\n\nfrom app.event_bus.audit_logger import write_audit_log\nfrom app.engine.emc.emc_manager import EmcManager, STRATEGY_ID\nfrom app.engine.emc.emc_engine import EmcEngine\n\n_MANAGER: Optional[EmcManager] = None\n_ENGINE: Optional[EmcEngine] = None\n\n\ndef get_emc_manager() -> Optional[EmcManager]:\n    return _MANAGER\n\n\ndef get_emc_engine() -> Optional[EmcEngine]:\n    return _ENGINE\n\n\nasync def emc_v1_runtime(broker_manager, *args, **kwargs):\n    global _MANAGER, _ENGINE\n    try:\n        await asyncio.sleep(0)\n        if _MANAGER is not None:\n            write_audit_log("[EMC][RUNTIME] already initialized — ignoring")\n            return\n        executor = None\n        try:\n            from app.execution.executor_factory import get_executor_for_strategy\n            executor = get_executor_for_strategy(STRATEGY_ID)\n            write_audit_log("[EMC][RUNTIME] executor pre-built")\n        except Exception as e:\n            write_audit_log(f"[EMC][RUNTIME] executor build failed ({e!r}) — PAPER unaffected; LIVE will alert "\n                            f"at entry")\n        _MANAGER = EmcManager(executor=executor)\n        _ENGINE = EmcEngine(_MANAGER, broker_manager)\n        _ENGINE.start()\n        try:\n            from app.execution import kill_switch\n            kill_switch.register_adapter(STRATEGY_ID, lambda: _MANAGER.kill_adapter())\n            write_audit_log("[EMC][RUNTIME] kill adapter registered")\n        except Exception as e:\n            write_audit_log(f"[EMC][RUNTIME] kill adapter failed: {e!r}")\n        write_audit_log("[EMC][RUNTIME] EMC_V1 runtime up (engine=on)")\n        while True:\n            await asyncio.sleep(60)\n            if _MANAGER.executor is None:\n                try:\n                    from app.execution.executor_factory import get_executor_for_strategy\n                    _MANAGER.attach_executor(get_executor_for_strategy(STRATEGY_ID))\n                    write_audit_log("[EMC][RUNTIME] executor re-attached")\n                except Exception:\n                    pass\n    except Exception as e:\n        write_audit_log(f"[EMC][RUNTIME][FATAL] {e!r}")\n        try:\n            from app.api.telegram_api import notify_system_alert\n            notify_system_alert({"message": f"EMC_V1 runtime died: {e!r}", "severity": "error"})\n        except Exception:\n            pass\n'

NEW_FILES['backend/app/engine/emc/test_emc_live.py'] = '# backend/app/engine/emc/test_emc_live.py\n#\n# ── EMC_V1_LIVE_20261011 ── behavioural suite for the paper/live engine. Standalone:\n#   cd backend && PYTHONPATH=$PWD python3 app/engine/emc/test_emc_live.py\n# A fake Kite replays a synthetic Black-76 corpus at a simulated clock; the REAL\n# EmcEngine + EmcManager trade it and are compared, trade by trade, with\n# run_emc_backtest on the same corpus. Then: restart, LIVE order flow,\n# reconcile-first exits, OFF mode, every fail-closed refusal.\nimport os, sys, sqlite3, tempfile\nfrom datetime import date, datetime, timedelta, timezone\nfrom types import SimpleNamespace as NS\n\nIST = 5 * 3600 + 30 * 60\nTZ = timezone(timedelta(hours=5, minutes=30))\n\n\nclass Clock:\n    def __init__(self, t=0): self.t = t\n    def __call__(self): return self.t\n\n\nclass FakeKite:\n    """historical_data / quote over a backtest corpus at the simulated time."""\n    def __init__(self, db, clock, spot_token=256265):\n        self.c = sqlite3.connect(db); self.c.row_factory = sqlite3.Row\n        self.clock = clock\n        self.spot_token = spot_token\n        self.tok2sym, self.sym2tok = {}, {}\n        for i, (s,) in enumerate(self.c.execute("SELECT DISTINCT tradingsymbol FROM backtest_candles_1m "\n                                                "WHERE instrument_type IN (\'CE\',\'PE\')")):\n            self.tok2sym[100000 + i] = s; self.sym2tok[s] = 100000 + i\n        self._cache = {}\n        self.calls = {"hist": 0, "quote": 0}\n\n    def _rows(self, sym_or_spot, day_start):\n        key = (sym_or_spot, day_start)\n        if key not in self._cache:\n            if sym_or_spot == "SPOT":\n                q = self.c.execute("SELECT ts,open,high,low,close FROM backtest_candles_1m WHERE underlying=\'NIFTY\' "\n                                   "AND instrument_type=\'SPOT\' AND ts>=? AND ts<? ORDER BY ts", (day_start, day_start + 86400))\n            else:\n                q = self.c.execute("SELECT ts,open,high,low,close FROM backtest_candles_1m WHERE tradingsymbol=? "\n                                   "AND ts>=? AND ts<? ORDER BY ts", (sym_or_spot, day_start, day_start + 86400))\n            self._cache[key] = {r["ts"]: dict(r) for r in q}\n        return self._cache[key]\n\n    @staticmethod\n    def _ds(ts): return ((int(ts) + IST) // 86400) * 86400 - IST\n\n    @staticmethod\n    def _epoch(dt):\n        if dt.tzinfo is None:\n            return int((dt - datetime(1970, 1, 1)).total_seconds()) - IST\n        return int(dt.timestamp())\n\n    def historical_data(self, instrument_token, from_date, to_date, interval):\n        self.calls["hist"] += 1\n        now = self.clock()\n        if interval == "day":\n            fr = self._epoch(datetime(from_date.year, from_date.month, from_date.day))\n            to = self._epoch(datetime(to_date.year, to_date.month, to_date.day)) + 86400\n            out = []\n            for (ts,) in self.c.execute("SELECT DISTINCT (ts + ?) / 86400 FROM backtest_candles_1m WHERE "\n                                        "instrument_type=\'SPOT\' AND ts>=? AND ts<?", (IST, fr, min(to, now))):\n                d = date(1970, 1, 1) + timedelta(days=int(ts))\n                out.append({"date": datetime(d.year, d.month, d.day, tzinfo=TZ), "open": 1, "high": 1, "low": 1, "close": 1})\n            return out\n        fr, to = self._epoch(from_date), self._epoch(to_date)\n        name = "SPOT" if int(instrument_token) == self.spot_token else self.tok2sym.get(int(instrument_token))\n        out = []\n        d = self._ds(fr)\n        while d <= to:\n            for ts, r in sorted(self._rows(name, d).items()):\n                if fr <= ts <= to and ts + 60 <= now:\n                    out.append({"date": datetime.fromtimestamp(ts, TZ), "open": r["open"], "high": r["high"],\n                                "low": r["low"], "close": r["close"], "volume": 0})\n            d += 86400\n        return out\n\n    def path_price(self, sym, t):\n        """Intraminute path open(0–5s) → low(25s) → high(45s) → close(59s)."""\n        m0 = t - t % 60\n        r = self._rows(sym, self._ds(t)).get(m0)\n        if r is None:\n            prev = [v for k, v in self._rows(sym, self._ds(t)).items() if k < m0]\n            return prev[-1]["close"] if prev else None\n        s = t % 60\n        o, h, l, c = r["open"], r["high"], r["low"], r["close"]\n        if s <= 5: return o\n        if s <= 25: return round(o + (l - o) * (s - 5) / 20, 2)\n        if s <= 45: return round(l + (h - l) * (s - 25) / 20, 2)\n        return round(h + (c - h) * (s - 45) / 14, 2)\n\n    def quote(self, keys):\n        self.calls["quote"] += 1\n        now = self.clock()\n        out = {}\n        for k in keys:\n            sym = k.split(":", 1)[1]\n            p = self.path_price(sym, now)\n            if p is not None:\n                out[k] = {"last_price": p}\n        return out\n\n\ndef make_chain_fn(kite, clock, expiry_fn, stf=5):\n    """Ideal snapshot AT THE CLOSE of the minute just completed (the\n    backtest\'s quotes_at rule: close at k, else last print in the spot bar)."""\n    def chain():\n        now = clock()\n        ds = FakeKite._ds(now)\n        k = ((now + IST) % 86400) // 60 - 1\n        d = (datetime.utcfromtimestamp(now + IST)).date()\n        exp = expiry_fn(d).isoformat()\n        rows, ltp = [], {}\n        for (sym, strike, it) in kite.c.execute("SELECT DISTINCT tradingsymbol, strike, instrument_type FROM "\n                                                "backtest_candles_1m WHERE expiry=? AND ts>=? AND ts<?", (exp, ds, ds + 86400)):\n            rows.append({"tradingsymbol": sym, "instrument_token": kite.sym2tok[sym], "strike": strike, "instrument_type": it})\n            bars = kite._rows(sym, ds)\n            px = None\n            for m in range(k, k - stf, -1):\n                b = bars.get(ds + m * 60)\n                if b is not None and b["close"]:\n                    px = float(b["close"]); break\n            ltp[sym] = px or 0.0\n        return date.fromisoformat(exp), rows, ltp\n    return chain\n\n\n# ═══════════════════════════════════ suite ═══════════════════════════════════\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, os.path.abspath(os.path.join(HERE, "..", "..", "..")))\nfrom app.backtest.replay import replay_synth                                   # noqa: E402\nfrom app.backtest.emc.backtest_emc_runner import run_emc_backtest, _day_start_epoch, DEFAULTS as BT_DEFAULTS  # noqa: E402\nfrom app.backtest.engine.expiry_calendar import expected_expiry_for_day        # noqa: E402\nfrom app.utils.market_hours import is_trading_day                              # noqa: E402\nimport app.engine.emc.emc_manager as MG                                        # noqa: E402\nfrom app.engine.emc.emc_engine import EmcEngine, EmcFeed                       # noqa: E402\nfrom app.engine.emc.emc_live_core import live_params, CrossGuard, LiveSpotCrosses  # noqa: E402\n\nFAILS, NPASS = [], [0]\n\n\ndef check(name, ok, note=""):\n    print(f"  {\'PASS\' if ok else \'FAIL\'}  {name}{(\'  — \' + str(note)) if (note and not ok) else \'\'}")\n    if ok:\n        NPASS[0] += 1\n    else:\n        FAILS.append(name)\n\n\nROWS = {}\n\n\ndef fake_insert(**k):\n    ROWS[k["paper_trade_id"]] = dict(k, exit_price=None, exit_reason=None)\n\n\ndef fake_close(paper_trade_id, exit_price, exit_reason, **k):\n    ROWS[paper_trade_id].update(exit_price=exit_price, exit_reason=exit_reason)\n\n\nMG.insert_paper_trade, MG.close_paper_trade = fake_insert, fake_close\nMG._DEGRADED.clear()\n\n\nclass Notif:\n    def __init__(self): self.sent = []\n    def __getattr__(self, n): return lambda payload: self.sent.append((n, payload))\n\n\nALERTS = []\nMG.record_alert = lambda code, msg, **k: ALERTS.append((code, msg, k.get("severity")))\n\n\nSEALED = {"trade_execution_mode": "PAPER", "lots": 1, "sel_prem_min": 60, "sel_prem_max": 140,\n          "ema_fast": 7, "ema_slow": 20, "sl_pts": 31, "tp_pts": 100, "entry_cutoff": "14:00",\n          "max_losses_per_day": 4, "arm_skip_from": "09:30", "arm_skip_to": "10:00"}\n\ntmp = tempfile.mkdtemp(prefix="emc_live_")\nDB = os.path.join(tmp, "backtest.db")\nreplay_synth.build(DB, d0=date(2025, 1, 1), d1=date(2025, 2, 28), strikes_each_side=8, with_fut=False)\n\n\ndef rows_today(mgr):\n    def today_rows(ds, rows=None):\n        return [dict(r) for r in sorted(ROWS.values(), key=lambda r: r["candle_ts"])\n                if r["candle_ts"] >= ds and not str(r["paper_trade_id"]).startswith("SHD:")]\n    def open_rows_any_day():\n        return [dict(r) for r in ROWS.values() if r["exit_price"] is None and r.get("exit_reason") is None]\n    mgr.today_rows, mgr.open_rows_any_day = today_rows, open_rows_any_day\n\n\ndef build(cfg, clock, kite, executor=None):\n    state = {"cfg": dict(cfg)}\n    mgr = MG.EmcManager(executor=executor, cfg_fn=lambda: dict(state["cfg"]), notifier=Notif(), clock=clock,\n                        sleep=lambda s: setattr(clock, "t", clock.t + s))\n    mgr.state_cfg = state\n    rows_today(mgr)\n    feed = EmcFeed(lambda: kite, chain_fn=make_chain_fn(kite, clock, expected_expiry_for_day))\n    eng = EmcEngine(mgr, feed=feed, clock=clock, sleep=lambda s: None, trading_day_fn=is_trading_day,\n                    expected_expiry_fn=expected_expiry_for_day)\n    return mgr, eng\n\n\ndef run_days(mgr, eng, clock, d0, d1, stop_at=None, start_at=None):\n    d = d0\n    while d <= d1:\n        if is_trading_day(d):\n            ds = _day_start_epoch(d)\n            for m in range(9 * 60 + 5, 15 * 60 + 31):\n                if start_at and ds + m * 60 < start_at:\n                    continue\n                busy = mgr.pos is not None\n                secs = range(60) if busy else (0, 1, 3, 4, 5, 8, 15, 30)\n                for s in secs:\n                    t = ds + m * 60 + s\n                    if stop_at and t >= stop_at:\n                        return\n                    clock.t = t\n                    eng.tick(t)\n                    if not busy and mgr.pos is not None:\n                        for s2 in range(s + 1, 60):\n                            clock.t = ds + m * 60 + s2\n                            eng.tick(clock.t)\n                        break\n        d += timedelta(days=1)\n\n\ndef compare(live_rows, bt_trades):\n    L = {(r["candle_ts"], r["symbol"]): r for r in live_rows}\n    B = {(t.entry_ts, t.tradingsymbol): t for t in bt_trades}\n    both = set(L) & set(B)\n    same_reason = sum(1 for k in both if L[k]["exit_reason"] == B[k].exit_reason)\n    entry_px = max((abs(L[k]["entry_price"] - B[k].entry_price) for k in both), default=0.0)\n    return len(L), len(B), len(both), same_reason, entry_px\n\n\nprint("── config: live reads the backtest runner\'s vocabulary ──")\np, m, bad = live_params(SEALED)\ncheck("sealed config accepted", bad is None and p is not None, bad)\ncheck("DayParams mapped exactly (SL 31 / TP 100 / cutoff 14:00 / EOD 15:15 / cap 4 / no-arm 09:30–10:00)",\n      p.sl_pts == 31 and p.tp_pts == 100 and p.block_min == 840 and p.eod_min == 915 and p.max_losses == 4\n      and p.skip_from == 570 and p.skip_to == 600 and p.opt_min_bars == 20 and p.intrabar and p.fill == "next_open")\nfor nm, over in (("trailing SL refused", {"trail_on": True}), ("fill_mode close refused", {"fill_mode": "close"}),\n                 ("runner guard: band inverted", {"sel_prem_min": 200, "sel_prem_max": 150}),\n                 ("runner guard: blackout half set", {"arm_skip_to": ""})):\n    check(nm, live_params(dict(SEALED, **over))[2] is not None)\ng = CrossGuard()\ng.check({559: 1, 604: -1}, 604)\ncheck("prefix guard freezes on a restated cross", not g.check({559: 1, 604: 1}, 609) and g.frozen)\n\nprint("── parity: live engine vs backtest, trade by trade ──")\nD0, D1 = date(2025, 1, 20), date(2025, 2, 28)\nfor name, cfg in (("sealed config", SEALED),\n                  ("spec defaults (EMA 9/21, SL 20, TP 40, no cap, no blackout)",\n                   dict(SEALED, ema_fast=9, ema_slow=21, sl_pts=20, tp_pts=40, entry_cutoff="14:30",\n                        max_losses_per_day=0, arm_skip_from="", arm_skip_to=""))):\n    ROWS.clear()\n    clock = Clock()\n    kite = FakeKite(DB, clock)\n    mgr, eng = build(cfg, clock, kite)\n    mgr.qty = lambda: (1, 65, 65)\n    run_days(mgr, eng, clock, D0, D1)\n    bt = run_emc_backtest(db_path=DB, strategy_id="EMC_V1", underlying="NIFTY", date_from=D0, date_to=D1,\n                          config_override=dict(cfg))["trades"]\n    nl, nb, nboth, sr, epx = compare(list(ROWS.values()), bt)\n    check(f"{name}: same trades ({nl} live / {nb} backtest)", nl == nb == nboth and nl >= 15, (nl, nb, nboth))\n    check(f"{name}: same exit reason on every trade", sr == nboth, (sr, nboth))\n    check(f"{name}: entry price = the backtest\'s next-minute open", epx < 0.005, epx)\n    check(f"{name}: every row closed, nothing carried overnight", all(r["exit_price"] is not None for r in ROWS.values()))\nBASE_ROWS = {k: dict(v) for k, v in ROWS.items()}\n\nprint("── restart mid-position: adopt, keep counters, same exit ──")\nROWS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nday = date(2025, 1, 21)\nfor dd in (date(2025, 1, 21), date(2025, 1, 22), date(2025, 1, 23), date(2025, 1, 24), date(2025, 1, 27)):\n    ROWS.clear()\n    clock = Clock(); kite = FakeKite(DB, clock)\n    mgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\n    run_days(mgr, eng, clock, dd, dd)\n    full = sorted(ROWS.values(), key=lambda r: r["candle_ts"])\n    if len(full) >= 2 and full[1]["exit_reason"] in ("SL", "TP", "XOVER", "EOD"):\n        day = dd\n        break\nref = sorted(ROWS.values(), key=lambda r: r["candle_ts"])\n# restart 2 minutes after the SECOND entry\nt_stop = ref[1]["candle_ts"] + 120\nROWS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day, stop_at=t_stop)\nbefore = {k: dict(v) for k, v in ROWS.items()}\nmgr2, eng2 = build(SEALED, clock, kite); mgr2.qty = lambda: (1, 65, 65)\nrun_days(mgr2, eng2, clock, day, day, start_at=t_stop)\nafter = sorted(ROWS.values(), key=lambda r: r["candle_ts"])\ncheck("restart adopts the open row (no duplicate entry)", len([r for r in after if r["symbol"] == ref[1]["symbol"]\n                                                                and r["candle_ts"] == ref[1]["candle_ts"]]) == 1)\ncheck("adopted position exits for the same reason as the uninterrupted day",\n      [r for r in after if r["candle_ts"] == ref[1]["candle_ts"]][0]["exit_reason"] == ref[1]["exit_reason"],\n      ([r["exit_reason"] for r in after], [r["exit_reason"] for r in ref]))\ncheck("day counters restored after restart", eng2.core is not None and eng2.core.day_entries >= 2)\ncheck("no trade after the restart that the uninterrupted day did not also take (pending setups are not resurrected)",\n      {(r["candle_ts"], r["symbol"]) for r in after} <= {(r["candle_ts"], r["symbol"]) for r in ref})\n\nprint("── LIVE order flow (fake executor) ──")\n\n\nclass FakeExec:\n    def __init__(self, kite, clock, holding=True, positions_ok=True, fill=True):\n        self.kite, self.clock = kite, clock\n        self.orders, self.sells, self.holding, self.positions_ok, self.fill = [], [], holding, positions_ok, fill\n        self.book = {}\n    def place_buy(self, symbol, token, qty):\n        px = self.kite.path_price(symbol, self.clock())\n        self.orders.append((symbol, qty, px))\n        if not self.fill:\n            return "B1", 0, 0\n        self.book[symbol] = qty\n        return f"B{len(self.orders)}", px, qty\n    def get_order_fill(self, oid):\n        if not self.fill:\n            return {"status": "OPEN", "found": True}\n        return {"status": "COMPLETE", "avg_price": self._last_px, "found": True}\n    def place_market_sell(self, symbol, qty):\n        self._last_px = self.kite.path_price(symbol, self.clock())\n        self.sells.append((symbol, qty, self._last_px))\n        self.book.pop(symbol, None)\n        return f"S{len(self.sells)}"\n    def get_open_positions_or_none(self):\n        if not self.positions_ok:\n            return None\n        return [{"tradingsymbol": s, "quantity": q} for s, q in self.book.items()] if self.holding else []\n\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nex = FakeExec(kite, clock)\nmgr, eng = build(dict(SEALED, trade_execution_mode="LIVE"), clock, kite, executor=ex); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day)\nlive_rows = sorted(ROWS.values(), key=lambda r: r["candle_ts"])\ncheck("LIVE: one buy and one sell per trade, rows booked as LIVE",\n      len(ex.orders) == len(live_rows) == len(ex.sells) and all(r["trade_mode"] == "LIVE" for r in live_rows),\n      (len(ex.orders), len(ex.sells), len(live_rows)))\ncheck("LIVE: same trades as PAPER on that day", [(r["candle_ts"], r["symbol"]) for r in live_rows]\n      == [(r["candle_ts"], r["symbol"]) for r in ref])\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nex = FakeExec(kite, clock, holding=False)\nmgr, eng = build(dict(SEALED, trade_execution_mode="LIVE"), clock, kite, executor=ex); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day)\ncheck("reconcile-first: broker shows no holding → row closed, NO sell order placed",\n      ex.orders and not ex.sells and any(c == "BROKER_FLAT" for c, _, _ in ALERTS))\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nex = FakeExec(kite, clock, positions_ok=False)\nmgr, eng = build(dict(SEALED, trade_execution_mode="LIVE"), clock, kite, executor=ex); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day)\ncheck("unreadable broker book → NO sell order, backoff + alert, position kept open",\n      ex.orders and not ex.sells and any(c == "BROKER_UNREADABLE" for c, _, _ in ALERTS) and mgr.pos is not None)\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nex = FakeExec(kite, clock, fill=False)\nmgr, eng = build(dict(SEALED, trade_execution_mode="LIVE"), clock, kite, executor=ex); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day)\ncheck("unfilled LIVE buy → no position, no row, critical alert", not ROWS and mgr.pos is None\n      and any(c == "FILL_TIMEOUT" and s == "critical" for c, _, s in ALERTS))\n\nprint("── modes, refusals, stale rows, late data, kill ──")\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(dict(SEALED, trade_execution_mode="OFF"), clock, kite); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day)\ncheck("OFF: no new entries", not ROWS)\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nt_mid = ref[0]["candle_ts"] + 60\nrun_days(mgr, eng, clock, day, day, stop_at=t_mid)\nhad_pos = mgr.pos is not None\nmgr.state_cfg["cfg"]["trade_execution_mode"] = "OFF"\nrun_days(mgr, eng, clock, day, day, start_at=t_mid)\ncheck("OFF with a position open: it is still managed to its exit, nothing new opens",\n      had_pos and len(ROWS) == 1 and all(r["exit_price"] is not None for r in ROWS.values()))\n\nfor nm, over, code in (("trailing SL", {"trail_on": True}, "CFG_REFUSED"),\n                       ("DTE skip", {"dte_lot_mult": {str(i): 0 for i in range(0, 8)}}, "DTE_SKIP")):\n    ROWS.clear(); ALERTS.clear()\n    clock = Clock(); kite = FakeKite(DB, clock)\n    mgr, eng = build(dict(SEALED, **over), clock, kite); mgr.qty = lambda: (1, 65, 65)\n    run_days(mgr, eng, clock, day, day)\n    check(f"{nm}: day refused, zero trades, alerted", not ROWS and eng.phase() == "REFUSED"\n          and any(c == code for c, _, _ in ALERTS), ALERTS[:2])\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\n_sess = eng.feed.sessions\neng.feed.sessions = lambda token, days: [] if int(token) == 256265 else _sess(token, days)\nrun_days(mgr, eng, clock, day, day)\ncheck("no spot warm-up: stays BOOTING/REFUSED, zero trades, alerted",\n      not ROWS and eng.phase() in ("BOOTING", "REFUSED") and any(c in ("WARMUP", "NO_WARMUP") for c, _, _ in ALERTS),\n      (eng.phase(), ALERTS[:3]))\n\nROWS.clear(); ALERTS.clear()\nROWS["OLD"] = {"paper_trade_id": "OLD", "strategy_name": "EMC_V1", "trade_mode": "LIVE", "symbol": "NIFTYOLD",\n               "token": 1, "side": "CE", "entry_price": 150.0, "candle_ts": _day_start_epoch(day) - 86400 + 40000,\n               "sl_price": 119, "tp_price": 250, "qty": 65, "lots": 1, "exit_price": None, "exit_reason": None}\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day, stop_at=_day_start_epoch(day) + 9 * 3600 + 20 * 60)\ncheck("prior-day open row closed as STALE at entry, never adopted, critical alert",\n      ROWS["OLD"]["exit_reason"] == "STALE" and ROWS["OLD"]["exit_price"] == 150.0 and mgr.pos is None\n      and any(c == "STALE_ROW" and s == "critical" for c, _, s in ALERTS))\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nfirst_dec = ref[0]["candle_ts"]                      # boundary of the first trade\'s decision minute\nlag = {"on": True}\n_h = kite.historical_data\ndef lagged(**k):\n    out = _h(**k)\n    if lag["on"] and k.get("interval") == "minute":\n        cut = clock() - 150                            # data arrives 2.5 min late around the decision\n        if first_dec - 300 < clock() < first_dec + 400:\n            out = [r for r in out if int(r["date"].timestamp()) + 60 <= cut]\n    return out\nkite.historical_data = lagged\nrun_days(mgr, eng, clock, day, day)\ncheck("data stall around a decision → that entry is forfeited (LATE_DECISION), never taken stale",\n      not any(r["candle_ts"] == first_dec for r in ROWS.values()) and any(c == "LATE_DECISION" for c, _, _ in ALERTS))\nkite.historical_data = _h\n\nROWS.clear(); ALERTS.clear()\nclock = Clock(); kite = FakeKite(DB, clock)\nmgr, eng = build(SEALED, clock, kite); mgr.qty = lambda: (1, 65, 65)\nrun_days(mgr, eng, clock, day, day, stop_at=ref[0]["candle_ts"] + 60)\nres = mgr.kill_adapter()\ncheck("kill adapter flattens and reports the kill_switch contract",\n      res["closed"] == 1 and res["remaining"] == 0 and isinstance(res["detail"], list) and mgr.pos is None)\ncheck("a manager-originated close is counted by the day core", eng.core.pos is None and len(eng.core.trades) == 1)\n\nprint("── state route ──")\ntry:\n    import app.engine.emc.emc_runtime as RT\n    from app.api.emc_state_routes import emc_state\n    RT._MANAGER, RT._ENGINE = mgr, eng\n    st = emc_state()\n    check("state route composes a payload from the live objects",\n          st.get("running") and st.get("phase") and "day" in st and st.get("mode") == "PAPER", st.get("error"))\n    RT._MANAGER = RT._ENGINE = None\n    check("state route is sane when the runtime never launched", emc_state().get("running") is False)\nexcept Exception as e:  # pragma: no cover\n    check("state route import", False, repr(e))\n\nif FAILS:\n    print(f"\\n{len(FAILS)} FAILURES: {FAILS}")\n    sys.exit(1)\nprint(f"\\nALL {NPASS[0]} EMC LIVE CHECKS PASSED")\n'

NEW_FILES['backend/app/api/emc_state_routes.py'] = '# backend/app/api/emc_state_routes.py\n#\n# ── EMC_V1 STATE ROUTES ── Fence: EMC_V1_LIVE_20261011\n# Read-only dashboard payload composed from manager + engine + day core\n# (isolated try/except; a sane payload when the runtime never launched).\n# Prices tick on the frontend via LTPStore (the engine publishes every quote).\n\nfrom __future__ import annotations\nfrom datetime import datetime, timedelta, timezone\nfrom fastapi import APIRouter\n\nrouter = APIRouter(prefix="/api/emc_v1", tags=["EMC_V1"])\nIST = timezone(timedelta(hours=5, minutes=30))\n\n_EMPTY = {"ok": True, "running": False, "strategy": "EMC_V1", "mode": "OFF", "phase": "OFFLINE",\n          "position": None, "setup": None, "spot": None, "ema": None, "last_cross": None, "day": {},\n          "cfg": {}, "heartbeat_ts": None, "trades": [], "frozen": False, "refused": None}\n\n\ndef _hm(m):\n    return None if m is None else f"{int(m) // 60:02d}:{int(m) % 60:02d}"\n\n\n@router.get("/state")\ndef emc_state():\n    try:\n        from app.engine.emc.emc_runtime import get_emc_manager, get_emc_engine\n        mgr, eng = get_emc_manager(), get_emc_engine()\n        if mgr is None:\n            return dict(_EMPTY)\n        out = dict(_EMPTY)\n        cfg = mgr.cfg() or {}\n        out.update({"running": True, "mode": mgr.mode(), "heartbeat_ts": getattr(eng, "last_poll_ts", None),\n                    "cfg": {k: cfg.get(k) for k in ("ema_fast", "ema_slow", "spot_tf", "opt_tf", "sel_prem_min",\n                                                    "sel_prem_max", "sl_pts", "tp_pts", "entry_cutoff",\n                                                    "eod_square_off", "max_losses_per_day", "arm_skip_from",\n                                                    "arm_skip_to", "lots")},\n                    "day": dict(mgr.day_stats or {})})\n        if eng is not None:\n            out["phase"] = eng.phase()\n            out["refused"] = eng.refused\n            sp = eng.spot\n            if sp is not None:\n                out["frozen"] = bool(sp.guard.frozen)\n                if sp.today:\n                    b = sp.today[-1]\n                    out["spot"] = {"close": b.close, "ts": b.ts}\n                f, s = sp.last_vals\n                out["ema"] = {"fast": f, "slow": s}\n                out["gap_cross"] = _hm(sp.gap_cross_min)\n            if eng.last_cross:\n                k, x = eng.last_cross\n                out["last_cross"] = {"at": _hm(k), "dir": "UP" if x > 0 else "DOWN"}\n            c = eng.core\n            if c is not None:\n                out["day"].update({"entries": c.day_entries, "losses": c.day_losses, "halted": c.halted,\n                                   "diag": dict(eng.diag)})\n                if c.setup is not None:\n                    st = c.setup\n                    out["setup"] = {"side": st["side"], "symbol": st["c"]["sym"], "sel_px": st["c"]["price"],\n                                    "armed_at": _hm(st["k"]), "warming": bool(st.get("unready"))}\n            out["dte"] = getattr(eng, "dte", None)\n            out["dte_tag"] = getattr(eng, "dte_tag", None)\n        p = mgr.pos\n        if p is not None:\n            out["position"] = {"symbol": p.symbol, "side": p.side, "mode": p.mode, "entry": p.entry_px,\n                               "qty": p.qty, "lots": p.lots, "sl": p.sl, "tp": p.tp, "entry_ts": p.entry_ts,\n                               "mark": p.mark, "row_id": p.row_id}\n        try:\n            from app.db.sqlite import get_conn\n            now = datetime.now(IST)\n            day0 = int(now.replace(hour=0, minute=0, second=0, microsecond=0).timestamp())\n            rows = get_conn().execute(\n                "SELECT paper_trade_id, symbol, side, trade_mode, entry_price, exit_price, exit_reason, qty,"\n                " state, entry_time, exit_time, sl_price, tp_price, pnl_value, net_pnl FROM paper_trades"\n                " WHERE strategy_name=\'EMC_V1\' AND candle_ts >= ? AND paper_trade_id NOT LIKE \'SHD:%\'"\n                " ORDER BY candle_ts DESC LIMIT 20", (day0,)).fetchall()\n            out["trades"] = [dict(r) for r in rows]\n        except Exception:\n            pass\n        return out\n    except Exception as e:\n        return dict(_EMPTY, ok=False, error=repr(e))\n\n\n@router.post("/square_off")\ndef emc_square_off():\n    try:\n        from app.engine.emc.emc_runtime import get_emc_manager\n        mgr = get_emc_manager()\n        if mgr is None:\n            return {"ok": False, "error": "runtime not up"}\n        return {"ok": True, "closed": mgr.kill_all()}\n    except Exception as e:\n        return {"ok": False, "error": repr(e)}\n'

NEW_FILES['backend/app/jobs/emc_live_eod.py'] = '# backend/app/jobs/emc_live_eod.py\n#\n# ── EMC_V1 EOD BACKSTOP ── 15:17 sweep UNDER the engine\'s own 15:15 square-off.\n# Fence: EMC_V1_LIVE_20261011. The generic 15:25 paper sweep is a second\n# backstop below this one for PAPER rows (no exemption — EMC is intraday).\n\nfrom __future__ import annotations\nfrom app.event_bus.audit_logger import write_audit_log\n\n\ndef emc_live_eod_job():\n    try:\n        from app.utils.market_hours import is_trading_day\n        from datetime import date\n        if not is_trading_day(date.today()):\n            return\n    except Exception:\n        pass\n    try:\n        from app.engine.emc.emc_runtime import get_emc_manager\n        mgr = get_emc_manager()\n        if mgr is None or mgr.pos is None:\n            return\n        n = mgr.eod_squareoff()\n        mgr._alert("EOD_BACKSTOP", f"backstop closed {n} position(s) — the engine\'s 15:15 exit did not fire; "\n                   "investigate", "critical")\n    except Exception as e:\n        write_audit_log(f"[EMC][EOD_JOB][ERR] {e!r}")\n'

NEW_FILES['frontend/src/strategies/emc/EMCPanel.jsx'] = '// frontend/src/strategies/emc/EMCPanel.jsx\n//\n// ── EMC_V1 dashboard panel ── ("Ember", EMC_V1_LIVE_20261011)\n// ORBPanel\'s layout and conventions: structure from /api/emc_v1/state every\n// 4 s, prices ticking from ltpMap between polls, two-tap square-off\n// (window.confirm is swallowed by Tauri). Shows the three things that make\n// EMC legible: the spot EMA state + last cross, the pending setup (armed\n// contract waiting for its own EMA alignment), and the open position against\n// its premium stop and target.\n\nimport { useEffect, useRef, useState } from "react";\nimport { getApiBase } from "../../api/base";\nimport { colors, spacing, pnlStyle } from "../../tokens";\nimport { stratName } from "../displayNames";\n\nconst ACCENT = "#e11d48";\n\nfunction normalizeSymbol(sym) { return sym ? sym.replace(/\\s+/g, "").toUpperCase() : sym; }\nfunction fmtInr(v) {\n  if (v == null || isNaN(v)) return "—";\n  const a = Math.abs(v);\n  const s = a >= 100 ? Math.round(a).toLocaleString("en-IN") : a.toFixed(2);\n  return `${v < 0 ? "−" : ""}₹${s}`;\n}\nfunction fmt2(v) { return v == null || isNaN(v) ? "—" : Number(v).toFixed(2); }\nfunction hhmm(ts) {\n  if (!ts) return "—";\n  const d = new Date((typeof ts === "number" ? ts : Date.parse(ts) / 1000) * 1000);\n  if (isNaN(d.getTime())) return "—";\n  return d.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: false, timeZone: "Asia/Kolkata" });\n}\nfunction ago(ts) {\n  if (!ts) return null;\n  const s = Math.max(0, Math.round(Date.now() / 1000 - ts));\n  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m`;\n}\n\nconst PHASE = {\n  OFFLINE:        ["#1f2937", "#9ca3af", "OFFLINE"],\n  PRE_OPEN:       ["#1c2a4a", "#93c5fd", "PRE-OPEN"],\n  BOOTING:        ["#1c2a4a", "#93c5fd", "BOOTING · loading warm-up"],\n  WAITING_CROSS:  ["#14351f", "#4ade80", "WAITING FOR A SPOT CROSS"],\n  SETUP_PENDING:  ["#3b2a05", "#fbbf24", "ARMED · waiting for the option\'s EMAs"],\n  IN_POSITION:    ["#3b0a1a", "#fb7185", "IN POSITION"],\n  HALTED:         ["#2a2a2a", "#d1d5db", "HALTED · daily losing-trade cap"],\n  NO_NEW_ENTRIES: ["#2a2a2a", "#d1d5db", "NO NEW ENTRIES"],\n  DONE:           ["#2a2a2a", "#d1d5db", "DAY DONE"],\n  REFUSED:        ["#3a1420", "#f87171", "DAY REFUSED"],\n  FROZEN:         ["#3a1420", "#f87171", "FROZEN — prefix guard"],\n};\n\nexport default function EMCPanel({ strategyId = "EMC_V1", ltpMap = {} }) {\n  const [st, setSt] = useState(null);\n  const [armed, setArmed] = useState(false);\n  const armTimer = useRef(null);\n\n  useEffect(() => {\n    let alive = true;\n    const pull = async () => {\n      try {\n        const r = await fetch(`${getApiBase()}/api/emc_v1/state`);\n        const d = await r.json();\n        if (alive) setSt(d);\n      } catch { /* backend down — keep last */ }\n    };\n    pull();\n    const t = setInterval(pull, 4000);\n    return () => { alive = false; clearInterval(t); };\n  }, []);\n\n  const squareOff = async () => {\n    if (!armed) {\n      setArmed(true);\n      clearTimeout(armTimer.current);\n      armTimer.current = setTimeout(() => setArmed(false), 4000);\n      return;\n    }\n    setArmed(false);\n    clearTimeout(armTimer.current);\n    try { await fetch(`${getApiBase()}/api/emc_v1/square_off`, { method: "POST" }); } catch { }\n  };\n\n  const pos = st?.position;\n  const setup = st?.setup;\n  const day = st?.day || {};\n  const cfg = st?.cfg || {};\n  const trades = st?.trades || [];\n  const phase = st?.phase || "OFFLINE";\n  const liveLtp = (sym) => {\n    if (!sym) return null;\n    const v = ltpMap[normalizeSymbol(sym)];\n    return typeof v === "number" && v > 0 ? v : null;\n  };\n  const posLtp = liveLtp(pos?.symbol) ?? pos?.mark ?? null;\n  const openMtm = pos && posLtp != null ? (posLtp - pos.entry) * pos.qty : null;\n  const closedPnl = trades.filter((t) => t.exit_price != null)\n    .reduce((a, t) => a + (t.net_pnl != null ? t.net_pnl : ((t.exit_price ?? 0) - t.entry_price) * t.qty), 0);\n  const dayTotal = closedPnl + (openMtm ?? 0);\n  const ema = st?.ema || {};\n  const trend = ema.fast != null && ema.slow != null ? (ema.fast > ema.slow ? "UP" : ema.fast < ema.slow ? "DOWN" : "FLAT") : null;\n\n  const card = { background: colors.bg.secondary, borderRadius: 10, padding: spacing.md,\n                 marginBottom: spacing.md, border: `1px solid ${colors.border.subtle}` };\n  const label = { fontSize: 11, color: colors.text.muted, textTransform: "uppercase", letterSpacing: 0.5 };\n  const num = { fontVariantNumeric: "tabular-nums" };\n  const chip = (bg, fg, text) => (\n    <span style={{ background: bg, color: fg, borderRadius: 6, padding: "2px 8px", fontSize: 11, fontWeight: 600, whiteSpace: "nowrap" }}>{text}</span>\n  );\n  const sideChip = (s) => chip(s === "CE" ? "#14351f" : "#3a1420", s === "CE" ? "#4ade80" : "#f87171", s);\n  const Stat = ({ k, v, sub, style }) => (\n    <div style={{ minWidth: 92 }}>\n      <div style={label}>{k}</div>\n      <div style={{ fontSize: 16, fontWeight: 700, ...num, ...style }}>{v}</div>\n      {sub && <div style={{ fontSize: 10.5, color: colors.text.muted }}>{sub}</div>}\n    </div>\n  );\n  const [pBg, pFg, pText] = PHASE[phase] || PHASE.OFFLINE;\n  const hb = ago(st?.heartbeat_ts);\n  const stale = st?.running && st?.heartbeat_ts && (Date.now() / 1000 - st.heartbeat_ts) > 20;\n  const lossCap = Number(cfg.max_losses_per_day) || 0;\n\n  // premium track: SL → TP\n  const ptrack = pos && posLtp != null && pos.sl != null && pos.tp != null && pos.tp > pos.sl\n    ? { f: Math.min(1, Math.max(0, (posLtp - pos.sl) / (pos.tp - pos.sl))), e: (pos.entry - pos.sl) / (pos.tp - pos.sl) } : null;\n\n  return (\n    <div style={{ padding: spacing.md, color: colors.text.primary }}>\n      <div style={{ display: "flex", alignItems: "center", gap: spacing.md, flexWrap: "wrap", marginBottom: spacing.md }}>\n        <div>\n          <div style={{ fontSize: 16, fontWeight: 800 }}>{stratName(strategyId)}\n            <span style={{ marginLeft: 8, fontSize: 11, color: colors.text.muted, fontWeight: 500 }}>Ember · EMA cross, spot arms · option fires</span>\n          </div>\n          <div style={{ fontSize: 11, color: colors.text.muted, marginTop: 2 }}>\n            NIFTY {cfg.spot_tf ?? 5}m EMA{cfg.ema_fast ?? 7}/{cfg.ema_slow ?? 20} cross → weekly option ₹{cfg.sel_prem_min ?? 150}–{cfg.sel_prem_max ?? 200} (highest) → bought on its own {cfg.opt_tf ?? 5}m EMA alignment · SL −{cfg.sl_pts ?? 31} / TP +{cfg.tp_pts ?? 100} pts · flat by {cfg.eod_square_off ?? "15:15"}\n          </div>\n        </div>\n        <span style={{ marginLeft: "auto", display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap" }}>\n          {chip(pBg, pFg, pText)}\n          {st?.mode === "LIVE" ? chip("#3a1420", "#f87171", "LIVE") : st?.mode === "PAPER" ? chip("#1c2a4a", "#93c5fd", "PAPER") : chip("#1f2937", "#9ca3af", st?.mode || "—")}\n          {st?.running && chip(stale ? "#3a1420" : colors.bg.tertiary, stale ? "#f87171" : colors.text.muted, stale ? `ENGINE STALE ${hb}` : `♥ ${hb ?? "…"}`)}\n        </span>\n      </div>\n\n      {(st?.frozen || (st?.refused && phase === "REFUSED")) && (\n        <div style={{ ...card, borderColor: "#f87171", background: "#3a1420", color: "#fecaca", fontSize: 12 }}>\n          <b>{st.frozen ? "PREFIX GUARD TRIPPED" : "DAY REFUSED"}</b> — {st.refused || "a spot cross was restated; no new setups today (an open position is still managed)."}\n        </div>\n      )}\n      {!st?.running && (\n        <div style={{ ...card, fontSize: 12, color: colors.text.muted }}>\n          Runtime not up — strategy disabled, not licensed, or the backend is still booting.\n        </div>\n      )}\n\n      <div style={{ ...card, display: "flex", gap: spacing.lg, flexWrap: "wrap", alignItems: "flex-start" }}>\n        <Stat k="Day P&L" v={fmtInr(dayTotal)} style={pnlStyle(dayTotal)} sub={openMtm != null ? `closed ${fmtInr(closedPnl)} · open ${fmtInr(openMtm)}` : "closed rows (net)"} />\n        <Stat k="NIFTY 1m" v={st?.spot ? Math.round(st.spot.close).toLocaleString("en-IN") : "…"} sub={st?.spot ? `last bar ${hhmm(st.spot.ts)}` : "no bars yet"} />\n        <Stat k={`EMA ${cfg.ema_fast ?? 7}/${cfg.ema_slow ?? 20}`} v={trend ?? "…"} style={{ color: trend === "UP" ? "#4ade80" : trend === "DOWN" ? "#f87171" : undefined }}\n              sub={ema.fast != null ? `${fmt2(ema.fast)} / ${fmt2(ema.slow)}` : "warming"} />\n        <Stat k="Last cross" v={st?.last_cross ? `${st.last_cross.dir} ${st.last_cross.at}` : "—"} sub={st?.gap_cross ? `gap cross ${st.gap_cross}` : `no arming ${cfg.arm_skip_from || "—"}–${cfg.arm_skip_to || "—"}`} />\n        <Stat k="Trades" v={day.entries ?? 0} sub={`losing ${day.losses ?? 0}${lossCap ? ` of ${lossCap}` : ""}${day.halted ? " · HALTED" : ""}`} />\n        <Stat k="Exits" v={Object.values(day.exits || {}).reduce((a, b) => a + b, 0)} sub={Object.entries(day.exits || {}).map(([k, v]) => `${k} ${v}`).join(" · ") || "—"} />\n      </div>\n\n      <div style={card}>\n        <div style={{ ...label, marginBottom: 8 }}>Setup · spot cross arms one contract, its own EMAs pull the trigger</div>\n        {!setup && <div style={{ fontSize: 12, color: colors.text.muted }}>{pos ? "In a position — new setups wait for the next spot cross." : "No pending setup."}</div>}\n        {setup && (\n          <div style={{ fontSize: 13, display: "flex", gap: spacing.lg, flexWrap: "wrap", alignItems: "center", ...num }}>\n            {sideChip(setup.side)}\n            <b>{setup.symbol}</b>\n            <span style={{ color: colors.text.muted }}>armed {setup.armed_at} at ₹{fmt2(setup.sel_px)}</span>\n            <span>LTP <b>{fmt2(liveLtp(setup.symbol))}</b></span>\n            {setup.warming && chip("#1c2a4a", "#93c5fd", "option EMA warming")}\n            <span style={{ color: colors.text.muted }}>buys when its EMA{cfg.ema_fast ?? 7} is {setup.side === "CE" ? "above" : "below"} EMA{cfg.ema_slow ?? 20} · expires at {cfg.entry_cutoff ?? "14:00"} or on the opposite cross</span>\n          </div>\n        )}\n      </div>\n\n      <div style={card}>\n        <div style={{ ...label, marginBottom: 8 }}>Open position · SL / TP checked every 2 s · engine exits (no GTT)</div>\n        {!pos && <div style={{ fontSize: 12, color: colors.text.muted }}>Flat.</div>}\n        {pos && (\n          <>\n            <div style={{ fontSize: 13, display: "flex", gap: spacing.lg, flexWrap: "wrap", alignItems: "center", marginBottom: 8 }}>\n              {sideChip(pos.side)}\n              <b>{pos.symbol}</b>\n              <span style={{ color: colors.text.muted }}>{pos.mode} · qty {pos.qty} ({pos.lots} lot{pos.lots > 1 ? "s" : ""}) · in since {hhmm(pos.entry_ts)}</span>\n              <span style={{ marginLeft: "auto", ...num }}>\n                LTP <b style={{ fontSize: 15 }}>{posLtp != null ? fmt2(posLtp) : "…"}</b>\n                {openMtm != null && <b style={{ ...pnlStyle(openMtm), marginLeft: 10 }}>{fmtInr(openMtm)}</b>}\n              </span>\n              <button onClick={squareOff}\n                style={{ cursor: "pointer", borderRadius: 8, padding: "6px 14px", fontWeight: 700, fontSize: 12,\n                         border: `1px solid ${armed ? "#f87171" : colors.border.subtle}`,\n                         background: armed ? "#3a1420" : colors.bg.tertiary, color: armed ? "#f87171" : colors.text.primary }}>\n                {armed ? "TAP AGAIN TO SQUARE OFF" : "Square off"}\n              </button>\n            </div>\n            <div style={{ position: "relative", height: 10, background: colors.bg.tertiary, borderRadius: 5, overflow: "hidden" }}>\n              {ptrack && <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${ptrack.f * 100}%`, borderRadius: 5,\n                                      background: `linear-gradient(90deg, #f87171, ${ACCENT} ${ptrack.e * 100}%, #4ade80)`, opacity: 0.85 }} />}\n              {ptrack && <div style={{ position: "absolute", left: `calc(${ptrack.e * 100}% - 1px)`, top: 0, bottom: 0, width: 2, background: colors.text.primary, opacity: 0.7 }} />}\n            </div>\n            <div style={{ display: "flex", justifyContent: "space-between", fontSize: 11, color: colors.text.muted, marginTop: 4, ...num }}>\n              <span>SL {fmt2(pos.sl)}</span>\n              <span>entry {fmt2(pos.entry)}</span>\n              <span>TP {fmt2(pos.tp)}</span>\n            </div>\n          </>\n        )}\n      </div>\n\n      <div style={card}>\n        <div style={{ ...label, marginBottom: 8 }}>Today · {trades.length} row{trades.length === 1 ? "" : "s"}</div>\n        {trades.length === 0 && <div style={{ fontSize: 12, color: colors.text.muted }}>No trades yet today.</div>}\n        {trades.length > 0 && (\n          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12, ...num }}>\n            <thead>\n              <tr style={{ color: colors.text.muted, textAlign: "left" }}>\n                {["Time", "Side", "Symbol", "Qty", "Entry", "Exit", "Reason", "Net"].map((h) => (\n                  <th key={h} style={{ fontWeight: 600, padding: "4px 6px", borderBottom: `1px solid ${colors.border.subtle}` }}>{h}</th>\n                ))}\n              </tr>\n            </thead>\n            <tbody>\n              {trades.map((t) => {\n                const pnl = t.exit_price != null ? (t.net_pnl != null ? t.net_pnl : (t.exit_price - t.entry_price) * t.qty) : null;\n                return (\n                  <tr key={t.paper_trade_id} style={{ borderBottom: `1px solid ${colors.border.subtle}` }}>\n                    <td style={{ padding: "4px 6px" }}>{hhmm(t.entry_time)}{t.exit_time ? `→${hhmm(t.exit_time)}` : ""}</td>\n                    <td style={{ padding: "4px 6px" }}>{sideChip(t.side)}</td>\n                    <td style={{ padding: "4px 6px" }}><b>{t.symbol}</b> <span style={{ color: colors.text.muted }}>{t.trade_mode}</span></td>\n                    <td style={{ padding: "4px 6px" }}>{t.qty}</td>\n                    <td style={{ padding: "4px 6px" }}>{fmt2(t.entry_price)}</td>\n                    <td style={{ padding: "4px 6px" }}>{t.exit_price != null ? fmt2(t.exit_price) : chip("#3b0a1a", "#fb7185", "OPEN")}</td>\n                    <td style={{ padding: "4px 6px" }}>{t.exit_reason || "—"}</td>\n                    <td style={{ padding: "4px 6px", fontWeight: 700, ...pnlStyle(pnl ?? 0) }}>{pnl != null ? fmtInr(pnl) : "—"}</td>\n                  </tr>\n                );\n              })}\n            </tbody>\n          </table>\n        )}\n      </div>\n\n      <div style={{ fontSize: 10.5, color: colors.text.muted, padding: "0 4px" }}>\n        Sealed 2026-10-11 · cutoff {cfg.entry_cutoff ?? "14:00"} · losing-trade cap {lossCap || "off"} · no arming {cfg.arm_skip_from || "—"}–{cfg.arm_skip_to || "—"} · {st?.dte_tag && st.dte_tag !== "base" ? `DTE ${st.dte ?? "?"} (${st.dte_tag}) · ` : ""}EMC_V1_Strategy_Bible_20261011.pdf\n      </div>\n    </div>\n  );\n}\n'

