def die(msg: str) -> None:
    print(f"\n✗ {msg}")
    sys.exit(1)


def git_dirty(repo: Path, rel: str) -> bool:
    try:
        out = subprocess.run(["git", "status", "--porcelain", "--", rel], cwd=repo,
                             capture_output=True, text=True, timeout=30).stdout
        return bool(out.strip())
    except Exception:
        return False


def find_esbuild(repo: Path):
    for c in (repo / "frontend/node_modules/.bin/esbuild", repo / "desktop/node_modules/.bin/esbuild"):
        if c.exists():
            return str(c)
    return shutil.which("esbuild")


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=os.environ.get("SCALP_REPO", "/Users/anbu/dev/scalp-app"))
    ap.add_argument("--allow-dirty", action="store_true")
    ap.add_argument("--skip-tests", action="store_true")
    ap.add_argument("--skip-esbuild", action="store_true")
    a = ap.parse_args()
    repo = Path(a.repo).expanduser().resolve()
    print(f"[{FENCE}] repo: {repo}")

    targets = sorted({f for f, _, _, _ in EDITS} | set(REPLACE))
    for rel in targets:
        p = repo / rel
        if not p.exists():
            die(f"missing {rel}")
        if FENCE in p.read_text(encoding="utf-8"):
            die(f"{rel} already carries {FENCE} — already applied, nothing to do")
    for rel in NEW_FILES:
        if (repo / rel).exists():
            die(f"{rel} already exists — already applied (or a stray copy); nothing written")
    if PARENT not in (repo / PARENT_FILE).read_text(encoding="utf-8"):
        die(f"parent fence {PARENT} not found in {PARENT_FILE} — apply apply_emc_v1_blackout.py first "
            "(note: GitHub main does not carry it yet — push your local EMC files)")
    for rel, marks in PREREQS.items():
        p = repo / rel
        if not p.exists():
            die(f"prerequisite file missing: {rel}")
        txt = p.read_text(encoding="utf-8")
        for mk in marks:
            if mk not in txt:
                die(f"prerequisite '{mk}' not found in {rel}")
    dirty = [rel for rel in targets if git_dirty(repo, rel)]
    if dirty and not a.allow_dirty:
        die("uncommitted changes in " + ", ".join(dirty) +
            " — commit/stash first (or --allow-dirty if they are just uncommitted EMC applies)")

    staged = {rel: (repo / rel).read_text(encoding="utf-8") for rel in targets}
    original = dict(staged)
    for rel, (sha, txt) in REPLACE.items():
        got = hashlib.sha256(staged[rel].encode("utf-8")).hexdigest()
        if got != sha:
            die(f"{rel} differs from the delivered {PARENT} version (sha {got[:12]} ≠ {sha[:12]}) — "
                f"not overwriting local changes")
        staged[rel] = txt
    for rel, old, new, count in EDITS:
        n = staged[rel].count(old)
        if n != count:
            die(f"anchor matched {n}× (need {count}) in {rel}:\n---\n{old[:300]}\n---")
        staged[rel] = staged[rel].replace(old, new)

    with tempfile.TemporaryDirectory() as td:
        for rel in [r for r in targets if r.endswith(".py")] + [r for r in NEW_FILES if r.endswith(".py")]:
            tp = Path(td) / Path(rel).name
            tp.write_text(staged[rel] if rel in staged else NEW_FILES[rel], encoding="utf-8")
            try:
                py_compile.compile(str(tp), doraise=True)
            except py_compile.PyCompileError as e:
                die(f"py_compile failed for staged {rel}: {e}")
        print("  ✓ py_compile: staged Python files")
        if not a.skip_esbuild:
            esb = find_esbuild(repo)
            if esb:
                for rel in [r for r in targets if r.endswith((".jsx", ".js"))] + \
                        [r for r in NEW_FILES if r.endswith((".jsx", ".js"))]:
                    tp = Path(td) / ("x_" + Path(rel).name)
                    tp.write_text(staged[rel] if rel in staged else NEW_FILES[rel], encoding="utf-8")
                    r = subprocess.run([esb, str(tp), "--loader:.js=jsx", "--loader:.jsx=jsx", "--log-level=error"],
                                       capture_output=True, text=True)
                    if r.returncode != 0:
                        die(f"esbuild could not parse staged {rel}:\n{r.stderr[:2000]}")
                print("  ✓ esbuild parsed every staged JS/JSX file")
            else:
                print("  ! esbuild not found — JSX parse gate skipped (the frontend build will check)")

    def rollback(reason: str) -> None:
        for rel in targets:
            (repo / rel).write_text(original[rel], encoding="utf-8")
            (repo / rel).with_name(Path(rel).name + f".bak-{FENCE}").unlink(missing_ok=True)
        for rel in NEW_FILES:
            (repo / rel).unlink(missing_ok=True)
        for d in ("backend/app/engine/emc", "frontend/src/strategies/emc"):
            try:
                (repo / d).rmdir()
            except OSError:
                pass
        die(reason + " — every file restored to its pre-apply content, new files removed")

    try:
        for rel in targets:
            p = repo / rel
            shutil.copy2(p, p.with_name(p.name + f".bak-{FENCE}"))
        for rel in targets:
            txt = staged[rel]
            if rel in REPLACE and FENCE not in txt:
                raise RuntimeError(f"internal: replacement for {rel} lacks the fence")
            (repo / rel).write_text(txt, encoding="utf-8")
        for rel, txt in NEW_FILES.items():
            (repo / rel).parent.mkdir(parents=True, exist_ok=True)
            (repo / rel).write_text(txt, encoding="utf-8")
    except Exception as e:
        rollback(f"write failed ({e!r})")
    for rel in list(targets) + list(NEW_FILES):
        print(f"  ✓ wrote {rel}")

    if not a.skip_tests:
        env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1",
                   PYTHONPATH=str(repo / "backend") + os.pathsep + os.environ.get("PYTHONPATH", ""))
        r = subprocess.run([sys.executable, "-c", SMOKE], cwd=repo / "backend", capture_output=True, text=True,
                           env=env, timeout=300)
        if r.returncode != 0:
            print(r.stdout[-3000:]); print(r.stderr[-3000:])
            rollback("real-import smoke FAILED")
        print("  ✓ real-import smoke: modules import, sealed defaults parse to the sealed DayParams, mode PAPER")
        for suite in SUITES:
            print(f"  … running {suite}")
            try:
                r = subprocess.run([sys.executable, suite], cwd=repo / "backend", capture_output=True,
                                   text=True, env=env, timeout=1800)
            except subprocess.TimeoutExpired:
                rollback(f"suite {suite} timed out")
            last = (r.stdout.strip().splitlines() or ["(no output)"])[-1]
            if r.returncode != 0 or "  FAIL  " in r.stdout:
                print(r.stdout[-6000:])
                print(r.stderr[-3000:])
                rollback(f"suite {suite} FAILED")
            print(f"  ✓ {Path(suite).name}: {last}")

    for rel in list(targets) + list(NEW_FILES):
        for src_pre, dst_pre in MIRRORS.items():
            if rel.startswith(src_pre) and (repo / dst_pre).exists():
                dst = repo / (dst_pre + rel[len(src_pre):])
                dst.parent.mkdir(parents=True, exist_ok=True)
                if dst.exists():
                    shutil.copy2(dst, dst.with_name(dst.name + f".bak-{FENCE}"))
                shutil.copy2(repo / rel, dst)
                print(f"  ✓ mirrored → {dst.relative_to(repo)}")

    print(f"\n✓ {FENCE} applied. Rebuild both (./desktop/build-scalp.sh both). EMC_V1 boots in PAPER, 1 lot.\n"
          f"  Settings → EMC V1 (mode / lots / DTE × lots) · Dashboard → EMC V1 panel. Deploy on a non-trading day.")


if __name__ == "__main__":
    main()
